print("\n" + "="*80)
print("GAIN, PHASE, AND DELAY MARGIN ANALYSIS")
print("="*80)

for axis_name, K1_axis_local, K2_axis_local, B_eff_axis_local, J_axis, col_idx in axes_data:
    # Create loop transfer function L(s) = C(s)*G(s)
    num_plant = [1]
    den_plant = [J_axis, 0, 0]  # J*s^2
    G_plant = ct.TransferFunction(num_plant, den_plant)
    
    # Controller with nominal gains
    num_controller = [K1_axis_local[1], K1_axis_local[0]]
    den_controller = [1]
    C = ct.TransferFunction(num_controller, den_controller)
    
    # Loop transfer function
    L = C * G_plant
    
    # Compute stability margins
    gm, pm, wgc, wpc = ct.margin(L)
    
    # Convert to dB
    gm_db = 20 * np.log10(gm) if gm > 0 else -np.inf
    
    # Compute delay margin: DM = PM / (ωpc * 180/π) [in seconds]
    if wpc > 0 and pm > 0:
        delay_margin = (pm * np.pi / 180) / wpc  # Convert PM to radians, then divide by ωpc
    else:
        delay_margin = np.inf
    
    # Print results
    print(f"\n{axis_name} Axis Stability Margins:")
    print(f"   Gain Margin:      {gm_db:8.2f} dB  (factor: {gm:.4f}) at ω = {wgc:.4f} rad/s")
    print(f"   Phase Margin:     {pm:8.2f} deg at ω = {wpc:.4f} rad/s")
    print(f"   Delay Margin:     {delay_margin*1000:8.2f} ms  ({delay_margin:.6f} s)")
    print(f"   → System can tolerate up to {delay_margin*1000:.2f} ms of time delay")
    
    # Create Bode plot (Gain and Phase stacked)
    ax_gain = fig.add_subplot(gs[1, col_idx])
    ax_phase = fig.add_subplot(gs[2, col_idx])
    
    # Generate frequency response
    omega = np.logspace(-2, 2, 1000)
    mag, phase, omega_resp = ct.frequency_response(L, omega)
    mag_db = 20 * np.log10(mag)
    phase_deg = phase * 180 / np.pi
    
    # Plot Gain
    ax_gain.semilogx(omega_resp, mag_db, 'b-', linewidth=2, label='Loop Gain L(s)')
    ax_gain.axhline(y=0, color='r', linestyle='--', linewidth=1.5, label='0 dB')
    
    # Mark gain crossover frequency
    if wgc > 0:
        ax_gain.axvline(x=wgc, color='orange', linestyle=':', linewidth=2, 
                       label=f'Gain Crossover: {wgc:.3f} rad/s')
        ax_gain.plot(wgc, 0, 'o', color='orange', markersize=8)
    
    # Mark gain margin
    if wpc > 0:
        ax_gain.axvline(x=wpc, color='purple', linestyle=':', linewidth=2,
                       label=f'Phase Crossover: {wpc:.3f} rad/s')
        # Find magnitude at phase crossover
        idx_pc = np.argmin(np.abs(omega_resp - wpc))
        mag_at_pc = mag_db[idx_pc]
        ax_gain.plot(wpc, mag_at_pc, 's', color='purple', markersize=8)
        
        # Draw gain margin
        ax_gain.annotate('', xy=(wpc, 0), xytext=(wpc, mag_at_pc),
                        arrowprops=dict(arrowstyle='<->', color='red', lw=2))
        ax_gain.text(wpc*1.2, mag_at_pc/2, f'GM={gm_db:.1f}dB', 
                    fontsize=9, color='red', fontweight='bold',
                    bbox=dict(boxstyle='round,pad=0.4', facecolor='white', alpha=0.8))
    
    ax_gain.grid(True, which='both', alpha=0.3, linestyle='--')
    ax_gain.set_ylabel('Magnitude (dB)', fontsize=10, fontweight='bold')
    ax_gain.set_title(f'{axis_name} Axis - Gain Margin: {gm_db:.2f} dB', 
                     fontsize=11, fontweight='bold')
    ax_gain.legend(loc='upper right', fontsize=8, framealpha=0.9)
    ax_gain.set_xlim([omega[0], omega[-1]])
    
    # Plot Phase
    ax_phase.semilogx(omega_resp, phase_deg, 'g-', linewidth=2, label='Phase L(s)')
    ax_phase.axhline(y=-180, color='r', linestyle='--', linewidth=1.5, label='-180°')
    
    # Mark phase crossover frequency
    if wgc > 0:
        ax_phase.axvline(x=wgc, color='orange', linestyle=':', linewidth=2)
        # Find phase at gain crossover
        idx_gc = np.argmin(np.abs(omega_resp - wgc))
        phase_at_gc = phase_deg[idx_gc]
        ax_phase.plot(wgc, phase_at_gc, 'o', color='orange', markersize=8)
        
        # Draw phase margin
        ax_phase.annotate('', xy=(wgc, -180), xytext=(wgc, phase_at_gc),
                         arrowprops=dict(arrowstyle='<->', color='blue', lw=2))
        ax_phase.text(wgc*1.2, -180 + (phase_at_gc + 180)/2, f'PM={pm:.1f}°', 
                     fontsize=9, color='blue', fontweight='bold',
                     bbox=dict(boxstyle='round,pad=0.4', facecolor='white', alpha=0.8))
    
    if wpc > 0:
        ax_phase.axvline(x=wpc, color='purple', linestyle=':', linewidth=2)
    
    ax_phase.grid(True, which='both', alpha=0.3, linestyle='--')
    ax_phase.set_xlabel('Frequency (rad/s)', fontsize=10, fontweight='bold')
    ax_phase.set_ylabel('Phase (deg)', fontsize=10, fontweight='bold')
    ax_phase.set_title(f'{axis_name} Axis - Phase Margin: {pm:.2f}° | Delay Margin: {delay_margin*1000:.2f} ms', 
                      fontsize=11, fontweight='bold')
    ax_phase.legend(loc='upper right', fontsize=8, framealpha=0.9)
    ax_phase.set_xlim([omega[0], omega[-1]])
    ax_phase.set_ylim([-270, 0])

