# ROOT LOCUS ANALYSIS: POLES, ZEROS, AND BREAKOUT POINTS
# ============================================

print("="*80)
print("ROOT LOCUS STRUCTURAL ANALYSIS")
print("="*80)

# Analysis for one axis (they're all identical)
axis_name = "Pitch"
K1_axis_analysis = K1_pitch
K2_axis_analysis = K2_pitch
J_axis_analysis = Jx

print(f"\nAnalyzing {axis_name} Axis as representative example...")
print("\n" + "-"*80)
print("SYSTEM STRUCTURE")
print("-"*80)

# Plant transfer function
print("\n1. PLANT MODEL: G(s) = 1/(J·s²)")
print(f"   • Moment of Inertia J = {J_axis_analysis:.6f} kg·m²")
print(f"   • Poles: 2 poles at s = 0 (double integrator)")
print(f"   • Physical meaning: Torque → Angular Acceleration → Angular Velocity → Angle")

# Controller transfer function
Kp = K1_axis_analysis[0]  # Position gain
Kd = K1_axis_analysis[1]  # Derivative (rate) gain
zero_location = -Kp / Kd

print("\n2. CONTROLLER: C(s) = Kd·s + Kp (PD Controller)")
print(f"   • Proportional gain Kp = {Kp:.4f}")
print(f"   • Derivative gain Kd = {Kd:.6f}")
print(f"   • Controller zero at s = -Kp/Kd = {zero_location:.4f}")
print(f"   • Physical meaning: Error damping + Rate damping")

# Loop transfer function
print("\n3. LOOP TRANSFER FUNCTION: L(s) = C(s)·G(s)")
print(f"   L(s) = (Kd·s + Kp) / (J·s²)")
print(f"   L(s) = ({Kd:.6f}·s + {Kp:.4f}) / ({J_axis_analysis:.6f}·s²)")
print(f"\n   Poles (n=2): s = 0, 0 (at origin, order 2)")
print(f"   Zeros (m=1): s = {zero_location:.4f}")
print(f"   Number of branches: n = 2")
print(f"   Branches to infinity: n - m = 2 - 1 = 1 branch")

print("\n" + "-"*80)
print("ROOT LOCUS BRANCH STRUCTURE")
print("-"*80)

print("\n✓ YES, the root locus is drawn CORRECTLY. Here's why:")
print("\n1. BRANCH ORIGINS (K=0):")
print("   • 2 branches start from the double pole at s = 0")
print("   • This creates the characteristic 'butterfly' or 'figure-8' shape")

print("\n2. BRANCH DESTINATIONS (K→∞):")
print(f"   • 1 branch terminates at the finite zero s = {zero_location:.4f}")
print("   • 1 branch goes to infinity along the real axis")
print("   • Asymptote angle: ±180° (along negative real axis)")

print("\n3. BREAKAWAY/BREAKIN POINTS:")
print("   • Where multiple branches meet and split")
print("   • Found by solving: d/ds[1 + K·L(s)] = 0")
print("   • OR equivalently: dK/ds = 0")

# Calculate breakout points analytically
# For L(s) = (Kd·s + Kp)/(J·s²)
# Closed-loop characteristic equation: 1 + K·L(s) = 0
# For root locus with respect to overall gain, we need to reformulate
# Actually, the root locus plotted is with respect to the loop gain
# Let's find breakout points properly

# For the specific transfer function (Kd·s + Kp)/(J·s²)
# Breakout condition: d/ds[N(s)/D(s)] = 0
# Where N(s) = Kd·s + Kp, D(s) = J·s²
# d/ds[D(s)/N(s)] = 0
# (2Js)(Kd·s + Kp) - (J·s²)(Kd) = 0
# 2Js·Kd·s + 2Js·Kp - J·s²·Kd = 0
# J·s²·Kd + 2J·s·Kp = 0
# s(Kd·s + 2·Kp) = 0

breakout_1 = 0
