# %% [cell 11] code
# SET-THEORETIC BARRIER FUNCTION PARAMETERS
# ============================================
# Theory: Barrier functions ensure tracking error bounds ||e|| < ε_max
# by adding a barrier gradient term to the adaptive law that grows
# large as error approaches the prescribed limit.

class BarrierConfig:
    """
    Configuration for set-theoretic barrier functions that guarantee
    tracking error constraints: |error| < E_MAX for each axis
    """
    
    # ========== TRACKING ERROR BOUNDS ==========
    # Maximum allowable tracking error per axis (safety limits)
    # These are HARD CONSTRAINTS that will be enforced by barrier functions
    E_MAX_PITCH = 15.0   # [degrees] - Maximum pitch tracking error
    E_MAX_ROLL = 15.0    # [degrees] - Maximum roll tracking error  
    E_MAX_YAW = 20.0     # [degrees] - Maximum yaw tracking error (less critical)
    
    # For rate errors (rad/s) - typically less critical than angle errors
    E_MAX_PITCH_RATE = 1.5  # [rad/s]
    E_MAX_ROLL_RATE = 1.5   # [rad/s]
    E_MAX_YAW_RATE = 2.0    # [rad/s]
    
    # ========== BARRIER ACTIVATION ==========
    # Fraction of E_MAX where barrier gradient activates (0.0 to 1.0)
    # e.g., 0.8 means barrier starts affecting control at 80% of limit
    # Lower values = earlier activation = smoother but more conservative
    BARRIER_ALPHA = 0.75   # Start barrier at 75% of error limit
    
    # ========== BARRIER TUNING ==========
    # Gain that scales the barrier gradient strength
    # Higher gain = stronger constraint enforcement but may cause oscillations
    # Rule of thumb: Start with 1.0 and increase if violations observed
    BARRIER_GAIN = {
        'pitch': 2.0,    # Moderate gain for pitch (critical axis)
        'roll': 2.0,     # Moderate gain for roll (critical axis) 
        'yaw': 1.5       # Lower gain for yaw (less critical)
    }
    
    # Smoothing parameter prevents gradient singularity exactly at boundary
    # Should be very small (~1% of error limit)
    # Smaller values = sharper barrier but numerical sensitivity
    BARRIER_SMOOTHING = 0.15  # [degrees] - smooth transition width (~1% of 15° limit)
    
    # ========== CONTROL CONSTRAINT HANDLING ==========
    # Safety margin below U_MAX for barrier-aware reference governor
    # Ensures control stays feasible even with barrier corrections
    U_FEASIBLE_MARGIN = 0.15  # Reserve 15% of control authority
    
    # Reference governor filter time constant (smooths reference modifications)
    TAU_REF_GOVERNOR = 0.2  # [seconds] - fast response to constraint violations
    
    # ========== ENABLE/DISABLE FLAGS ==========
    ENABLE_ERROR_BARRIER = True      # Toggle tracking error barriers
    ENABLE_CONTROL_BARRIER = False    # Toggle control constraint enforcement via ref governor
    
    # Use composite barrier (single constraint on ||e||) vs per-element barriers
    USE_COMPOSITE_BARRIER = False    # False = separate barriers per axis (recommended)
    
    # Weight angle vs rate errors in composite barrier
    # Only used if USE_COMPOSITE_BARRIER = True
    ANGLE_RATE_WEIGHT = 1.0  # 1.0 = equal weighting, >1 = prioritize angle errors

print("Set-Theoretic Barrier Function parameters defined.")
print(f"  Error constraints: Pitch ±{BarrierConfig.E_MAX_PITCH}°, Roll ±{BarrierConfig.E_MAX_ROLL}°, Yaw ±{BarrierConfig.E_MAX_YAW}°")
print(f"  Barrier activation: {BarrierConfig.BARRIER_ALPHA*100:.0f}% of limit")
print(f"  Control margin: {BarrierConfig.U_FEASIBLE_MARGIN*100:.0f}% reserved")
