def get_scheduled_gamma(t, gamma_final, tau):
    """
    Exponential gamma scheduling.
    Starts at 0 and ramps up to gamma_final with time constant tau.
    """
    return gamma_final * (1.0 - np.exp(-t / tau))

def wrap_angle(angle_rad):
    """
    Wraps angle to [-π, π] range.
    Critical for Yaw axis to prevent unbounded angle accumulation.
    """
    return np.arctan2(np.sin(angle_rad), np.cos(angle_rad))

def Simple_rbf(x, c, width):
    """
    Simple Radial Basis Function (Gaussian) for 1D input.
    Args:
        x: input value (angle or angle_rate)
        c: center of the RBF
        width: width parameter (larger = wider activation)
    """
    return np.exp(-width * abs(x - c)**2)

def Joint_rbf(x0, x1, c0, c1, width):
    """
    Joint Radial Basis Function (Gaussian) for 2D input.
    Creates RBF activation based on distance in 2D state space (angle, rate).
    Args:
        x0: first state value (angle)
        x1: second state value (angle_rate)
        c0: center for first state
        c1: center for second state
        width: width parameter (larger = wider activation)
    """
    return np.exp(-width * ((x0 - c0)**2 + (x1 - c1)**2))


def compute_basis(bias, angle, angle_rate, gyroscopic_coupling, structured_unc, axis, D_range=None, use_joint_rbf=False):
    """
    Computes the base regressor vector (Phi) containing physical features.
    
    Args:
        bias: constant term (always 1.0)
        angle: current angle [rad]
        angle_rate: current angular velocity [rad/s]
        gyroscopic_coupling: product of other axes rates
        structured_unc: if True, use physics-based features; if False, use RBF
        axis: axis name (used only for error messages)
        D_range: for RBF mode, dict with 'angle' and 'rate' keys, each (start, end, num_rbfs)
        use_joint_rbf: if True, use joint RBF (2D grid); if False, use simple RBF (separate)
        
    Returns:
        theta: regressor vector [NUM_BASIS_BASE x 1]
    """
    if structured_unc:
        # Physics-based structured uncertainty model
        # 1. Constant bias (e.g., CoM offset)
        # 2. Angle proportional (e.g., spring-like effects)
        # 3. Rate proportional (e.g., damping)
        # 4. Nonlinear drag (e.g., aerodynamic drag ~ rate^2)
        # 5. Sinusoidal gravity (e.g., pendulum effect)
        # 6. Gyroscopic coupling from other axes
        theta = np.array([
            [bias],
            [angle],
            [angle_rate],
            [angle_rate * np.tanh(angle_rate)], 
            [np.sin(angle)],
            [gyroscopic_coupling]
        ]) 
    else:
        # Unstructured uncertainty using RBF network
        # D_range should be a dict with 'angle' and 'rate' keys
        # Each contains (start, end, num_rbfs)
        
        if D_range is None:
            raise ValueError("D_range must be provided for unstructured uncertainty mode")
        
        if use_joint_rbf:
            # JOINT RBF MODE: 2D grid of (angle, rate) centers
            # Extract ranges
            start_ang, end_ang, num_centers_ang = D_range['angle']
            start_rate, end_rate, num_centers_rate = D_range['rate']
            width = D_range.get('width', 0.5)  # Joint RBF width parameter
            
            # Create grid of centers
            centers_ang = np.linspace(start_ang, end_ang, num_centers_ang)
            centers_rate = np.linspace(start_rate, end_rate, num_centers_rate)
            
            # Compute joint RBF activations for all (angle, rate) pairs
            rbf_features = []
            for c_ang in centers_ang:
                for c_rate in centers_rate:
                    rbf_features.append([Joint_rbf(angle, angle_rate, c_ang, c_rate, width)])
            
            theta = np.array(rbf_features)
            
        else:
            # SIMPLE RBF MODE: Separate RBFs for angle and rate
            # Extract ranges for angle and angular rate
            start_ang, end_ang, num_rbfs_ang = D_range['angle']
            start_rate, end_rate, num_rbfs_rate = D_range['rate']
            
            # Create RBF centers for angle
            centers_ang = np.linspace(start_ang, end_ang, num_rbfs_ang)
            width_ang = 1.0 / ((end_ang - start_ang) / num_rbfs_ang)**2
            
            # Create RBF centers for angular rate
            centers_rate = np.linspace(start_rate, end_rate, num_rbfs_rate)
            width_rate = 1.0 / ((end_rate - start_rate) / num_rbfs_rate)**2
            
            # Compute RBF activations for ANGLE
            rbf_features = []
            for center in centers_ang:
                rbf_features.append([Simple_rbf(angle, center, width_ang)])
            
            # Compute RBF activations for ANGULAR RATE
            for center in centers_rate:
                rbf_features.append([Simple_rbf(angle_rate, center, width_rate)])
            
            theta = np.array(rbf_features)
    
    return theta

def compute_extended_regressor(theta_base, un_axis, v_axis):
    """
    Extends the base regressor with control signals.
    Allows the adaptive law to compensate for input effectiveness uncertainty (Lambda).
    
    Returns: [theta_base; un; v]
    """
    return np.vstack([theta_base, [[un_axis]], [[v_axis]]])

