def compute_time_varying_uncertainty(t, x, level='medium', use_structured=True, num_rbf_per_state=3, use_joint_rbf=False):
    """
    Generates synthetic 'True' uncertainty weights (W_true) to simulate
    disturbances and unmodeled dynamics.
    
    Args:
        t: current time
        x: state vector
        level: difficulty level ('easy', 'medium', 'hard')
        use_structured: if True, use physics-based weights; if False, use RBF weights
        num_rbf_per_state: number of RBF neurons per state (angle or rate) - only used when use_structured=False
        use_joint_rbf: if True, use joint RBF (2D grid); if False, use simple RBF (separate)
    
    Levels:
    - 'easy': Slowly changing drag
    - 'medium': Mass/Payload shifts
    - 'hard': Aggressive aerobatics/stall conditions
    """
    # Extract states
    pitch, pitch_dot = x[0, 0], x[1, 0]
    roll, roll_dot = x[2, 0], x[3, 0]
    
    if use_structured:
        # STRUCTURED UNCERTAINTY: Physics-based features
        # [bias, angle, rate, drag, sin, gyro]
        
        if level == 'medium':
            # Piecewise time-varying scenario (Payload shift)
            if t < 30: mass_shift = 0.0
            elif t < 35: mass_shift = (t - 30) / 5.0
            elif t < 60: mass_shift = 1.0
            elif t < 65: mass_shift = 1.0 - (t - 60) / 5.0
            else: mass_shift = 0.0
            
            coupling_gain = 0.08 + 0.12 * mass_shift
            bias_offset = 0.15 * mass_shift
            
            W_pitch = np.array([[0.1+bias_offset], [0.05], [0.02], [0.15], [0.03+0.02*mass_shift], [coupling_gain]])
            W_roll  = np.array([[0.1+bias_offset], [0.05], [0.02], [0.15], [0.03+0.02*mass_shift], [coupling_gain]])
            W_yaw   = np.array([[0.05], [0.08+0.05*mass_shift], [0.01], [0.0], [0.02], [coupling_gain]])
            
        elif level == 'hard':
            # High frequency vibrations + stall effects
            vibe = 0.02 * np.sin(15 * t)
            stall_p = 0.3 if np.abs(pitch_dot) > 0.35 else 0.0
            
            W_pitch = np.array([[0.1+vibe], [0.05], [0.02+stall_p], [0.15], [0.03], [0.08]])
            W_roll  = np.array([[0.1+vibe], [0.05], [0.02], [0.15], [0.03], [0.08]])
            W_yaw   = np.array([[0.05], [0.08], [0.01], [0.0], [0.02], [0.06]])
            
        else: # Easy
            drag = 0.1 + 0.05 * np.sin(0.2 * t)
            W_pitch = np.array([[0.1], [0.05], [0.02*drag], [0.15*drag], [0.03], [0.08]])
            W_roll  = np.array([[0.1], [0.05], [0.02*drag], [0.15*drag], [0.03], [0.07]])
            W_yaw   = np.array([[0.05], [0.08], [0.01*drag], [0.0], [0.02], [0.06]])
    
    else:
        # UNSTRUCTURED UNCERTAINTY: RBF-based approximation
        # Weights represent activation strengths for each RBF center
        
        if use_joint_rbf:
            # JOINT RBF MODE: 2D grid weights
            # Structure: weights for each (angle, rate) pair in grid
            total_rbfs = num_rbf_per_state * num_rbf_per_state
            
            if level == 'medium':
                # Create 2D Gaussian pattern centered in grid
                if t < 30: mass_shift = 0.0
                elif t < 35: mass_shift = (t - 30) / 5.0
                elif t < 60: mass_shift = 1.0
                elif t < 65: mass_shift = 1.0 - (t - 60) / 5.0
                else: mass_shift = 0.0
                
                # Generate 2D Gaussian pattern
                weights_2d = []
                center_idx = num_rbf_per_state // 2
                for i in range(num_rbf_per_state):
                    for j in range(num_rbf_per_state):
                        # Distance from center
                        dist = np.sqrt((i - center_idx)**2 + (j - center_idx)**2)
                        base_weight = 0.15 + 0.15 * np.exp(-0.3 * dist**2)
                        variation = base_weight * 0.4 * mass_shift
                        weights_2d.append([base_weight + variation])
                
                W_pitch = np.array(weights_2d)
                W_roll  = np.array(weights_2d) * 0.9
                W_yaw   = np.array(weights_2d) * 0.7
                
            elif level == 'hard':
                vibe = 0.03 * np.sin(15 * t)
                stall_effect = 0.2 if np.abs(pitch_dot) > 0.35 else 0.0
                
                # Asymmetric pattern with diagonal gradient
                weights_2d = []
                for i in range(num_rbf_per_state):
                    for j in range(num_rbf_per_state):
                        diag_factor = (i + j) / (2 * (num_rbf_per_state - 1))
                        weight = 0.10 + 0.20 * diag_factor + vibe
                        if i == num_rbf_per_state // 2 and j == num_rbf_per_state // 2:
                            weight += stall_effect
                        weights_2d.append([weight])
                
                W_pitch = np.array(weights_2d)
                W_roll  = np.array(weights_2d) * 0.95
                W_yaw   = np.array(weights_2d) * 0.75
                
            else:  # Easy
                drag = 0.1 + 0.05 * np.sin(0.2 * t)
                
                # Smooth 2D Gaussian centered in grid
                weights_2d = []
                center_idx = num_rbf_per_state // 2
                for i in range(num_rbf_per_state):
                    for j in range(num_rbf_per_state):
                        dist = np.sqrt((i - center_idx)**2 + (j - center_idx)**2)
                        weight = (0.15 + 0.10 * np.exp(-0.4 * dist**2)) * drag
                        weights_2d.append([weight])
                
                W_pitch = np.array(weights_2d)
                W_roll  = np.array(weights_2d) * 0.9
                W_yaw   = np.array(weights_2d) * 0.7
                
        else:
            # SIMPLE RBF MODE: Separate for angle and rate
            # Structure: [num_rbf_per_state angle RBFs, num_rbf_per_state rate RBFs]
            
            if level == 'medium':
                # Piecewise time-varying scenario (Payload shift)
                # Simulate smooth nonlinear disturbance pattern across RBF centers
                if t < 30: mass_shift = 0.0
                elif t < 35: mass_shift = (t - 30) / 5.0
                elif t < 60: mass_shift = 1.0
                elif t < 65: mass_shift = 1.0 - (t - 60) / 5.0
                else: mass_shift = 0.0
                
                # Create smooth disturbance profile across RBF space
                # Generate patterns based on num_rbf_per_state
                # For angle RBFs: bell-shaped pattern (higher weights in center)
                angle_indices = np.arange(num_rbf_per_state)
                center_idx = num_rbf_per_state // 2
                angle_weights = 0.15 + 0.15 * np.exp(-0.5 * ((angle_indices - center_idx) / (num_rbf_per_state / 3))**2)
                angle_rbf_pattern = angle_weights.reshape(-1, 1)
                
                # For rate RBFs: smoother pattern
                rate_weights = 0.20 + 0.05 * np.cos(np.pi * angle_indices / (num_rbf_per_state - 1))
                rate_rbf_pattern = rate_weights.reshape(-1, 1)
                
                # Mass shift variations
                angle_variation = angle_rbf_pattern * 0.4 * mass_shift
                rate_variation = rate_rbf_pattern * 0.4 * mass_shift
                
                W_pitch = np.vstack([angle_rbf_pattern + angle_variation, 
                                     rate_rbf_pattern + rate_variation])
                W_roll  = np.vstack([angle_rbf_pattern + angle_variation * 0.8, 
                                     rate_rbf_pattern + rate_variation * 0.8])
                W_yaw   = np.vstack([angle_rbf_pattern * 0.6 + angle_variation * 0.5, 
                                     rate_rbf_pattern * 0.6 + rate_variation * 0.5])
                
            elif level == 'hard':
                # High frequency vibrations + aggressive disturbances
                vibe = 0.03 * np.sin(15 * t)
                stall_effect = 0.2 if np.abs(pitch_dot) > 0.35 else 0.0
                
                # Generate asymmetric patterns
                angle_indices = np.arange(num_rbf_per_state)
                
                # Pitch: affected by vibration and stall
                pitch_angle_weights = 0.10 + 0.20 * (angle_indices / (num_rbf_per_state - 1)) + vibe
                pitch_angle_weights[num_rbf_per_state // 2] += stall_effect
                pitch_rate_weights = 0.25 - 0.10 * (angle_indices / (num_rbf_per_state - 1))
                
                # Roll: affected by vibration
                roll_angle_weights = 0.10 + 0.20 * (angle_indices / (num_rbf_per_state - 1)) + vibe
                roll_rate_weights = 0.25 - 0.10 * (angle_indices / (num_rbf_per_state - 1))
                
                # Yaw: smoother pattern
                yaw_angle_weights = 0.08 + 0.12 * (angle_indices / (num_rbf_per_state - 1))
                yaw_rate_weights = 0.20 - 0.10 * (angle_indices / (num_rbf_per_state - 1))
                
                W_pitch = np.vstack([pitch_angle_weights.reshape(-1, 1), pitch_rate_weights.reshape(-1, 1)])
                W_roll  = np.vstack([roll_angle_weights.reshape(-1, 1), roll_rate_weights.reshape(-1, 1)])
                W_yaw   = np.vstack([yaw_angle_weights.reshape(-1, 1), yaw_rate_weights.reshape(-1, 1)])
                
            else: # Easy
                # Slowly varying smooth disturbance
                drag = 0.1 + 0.05 * np.sin(0.2 * t)
                
                # Generate smooth symmetric patterns
                angle_indices = np.arange(num_rbf_per_state)
                center_idx = num_rbf_per_state // 2
                
                # Bell-shaped for angle RBFs
                angle_weights = 0.10 + 0.12 * np.exp(-0.5 * ((angle_indices - center_idx) / (num_rbf_per_state / 3))**2)
                # Smooth for rate RBFs
                rate_weights = 0.18 + 0.04 * np.cos(np.pi * angle_indices / (num_rbf_per_state - 1))
                
                base_pattern = np.vstack([angle_weights.reshape(-1, 1), rate_weights.reshape(-1, 1)])
                
                W_pitch = base_pattern * drag
                W_roll  = base_pattern * drag * 0.9
                W_yaw   = base_pattern * drag * 0.7
    
    return W_pitch, W_roll, W_yaw

def compute_reference_trajectory(t, level='easy'):
    """
    Generate realistic time-varying reference trajectories for drone attitude control.
    
    Parameters:
    -----------
    t : float
        Current simulation time [seconds]
    level : str or int
        Difficulty level: 'easy'/'1', 'medium'/'2', 'hard'/'3', 'extreme'/'4'
        
    Returns:
    --------
    r : np.ndarray (3x1)
        Reference angles [pitch, roll, yaw] in RADIANS
        
    Physical Scenarios:
    -------------------
    Level 1 (easy): Slow stabilization and gentle transitions
        - Hover stabilization → gentle tilt → return to level
        - Step responses with long settle times
        - Typical for: GPS waypoint navigation, aerial photography
        
    Level 2 (medium): Dynamic maneuvering with coupled motions
        - Coordinated turns (simultaneous pitch/roll/yaw)
        - Rectangular flight pattern
        - Typical for: FPV racing (moderate speed), inspection tasks
        
    Level 3 (hard): Aggressive aerobatic flight
        - Fast attitude changes, flips, high-rate maneuvers
        - Continuous sinusoidal excitation (multiple frequencies)
        - Typical for: FPV racing (high speed), aerobatics, evasive maneuvers
        
    Level 4 (extreme): Chaotic/unpredictable disturbance rejection
        - Random walk + sinusoidal + step changes
        - Multi-frequency excitation with varying amplitudes
        - Typical for: Extreme turbulence, emergency recovery, stress testing
    """
    
    deg2rad = np.pi / 180.0
    
    # ========================================================================
    # LEVEL 1: SLOW STABILIZATION AND GENTLE TRANSITIONS (EASY)
    # ========================================================================
    if level in ['easy', '1', 'level1', 1]:
        # Smooth step sequence with long dwell times
        if t < 20:
            # Initial hover (level attitude)
            pitch = 0.0
            roll = 0.0
            yaw = 0.0
        elif t < 40:
            # Forward tilt (slow acceleration)
            pitch = 8.0 * deg2rad
            roll = 0.0
            yaw = 0.0
        elif t < 60:
            # Left tilt with slight yaw
            pitch = 0.0
            roll = -8.0 * deg2rad
            yaw = 10.0 * deg2rad
        elif t < 80:
            # Return to level
            pitch = 0.0
            roll = 0.0
            yaw = 0.0
        else:
            # Backward tilt
            pitch = -8.0 * deg2rad
            roll = 0.0
            yaw = 0.0
    
    # ========================================================================
    # LEVEL 2: DYNAMIC MANEUVERING - RECTANGULAR PATTERN (MEDIUM)
    # ========================================================================
    elif level in ['medium', '2', 'level2', 2]:
        # Simulates rectangular flight pattern with coordinated turns
        phase = t % 40  # 40-second cycle
        
        if phase < 8:
            # Leg 1: Forward flight (pitch forward, level roll)
            pitch = 12.0 * deg2rad
            roll = 0.0
            yaw = 0.0 * deg2rad
        elif phase < 10:
            # Turn 1: Right turn (reduce pitch, roll right, yaw right)
            transition = (phase - 8) / 2.0  # 0 → 1 over 2 seconds
            pitch = 12.0 * (1 - transition) * deg2rad
            roll = 15.0 * transition * deg2rad
            yaw = 45.0 * transition * deg2rad
        elif phase < 18:
            # Leg 2: Right strafe
            pitch = 0.0
            roll = 12.0 * deg2rad
            yaw = 90.0 * deg2rad
        elif phase < 20:
            # Turn 2: Transition to backward
            transition = (phase - 18) / 2.0
            pitch = -12.0 * transition * deg2rad
            roll = 12.0 * (1 - transition) * deg2rad
            yaw = 90.0 + 45.0 * transition * deg2rad
        elif phase < 28:
            # Leg 3: Backward flight
            pitch = -12.0 * deg2rad
            roll = 0.0
            yaw = 180.0 * deg2rad
        elif phase < 30:
            # Turn 3: Left turn
            transition = (phase - 28) / 2.0
            pitch = -12.0 * (1 - transition) * deg2rad
            roll = -15.0 * transition * deg2rad
            yaw = 180.0 + 45.0 * transition * deg2rad
        elif phase < 38:
            # Leg 4: Left strafe
            pitch = 0.0
            roll = -12.0 * deg2rad
            yaw = 270.0 * deg2rad
        else:
            # Turn 4: Return to start
            transition = (phase - 38) / 2.0
            pitch = 12.0 * transition * deg2rad
            roll = -12.0 * (1 - transition) * deg2rad
            yaw = 270.0 + 45.0 * transition * deg2rad
    
    # ========================================================================
    # LEVEL 3: AGGRESSIVE AEROBATIC FLIGHT (HARD)
    # ========================================================================
    elif level in ['hard', '3', 'level3', 3]:
        # Multi-frequency sinusoidal excitation
        # Simulates aggressive FPV racing or aerobatic maneuvers
        
        # Pitch: Fast oscillation (0.3 Hz) + slow trend (0.05 Hz)
        pitch = (15.0 * np.sin(0.3 * 2*np.pi * t) + 
                 8.0 * np.sin(0.05 * 2*np.pi * t)) * deg2rad
        
        # Roll: Different frequency (0.25 Hz) + amplitude modulation
        amplitude_mod = 1.0 + 0.3 * np.sin(0.08 * 2*np.pi * t)
        roll = 18.0 * amplitude_mod * np.sin(0.25 * 2*np.pi * t) * deg2rad
        
        # Yaw: Continuous spinning with varying rate
        yaw_rate = 30.0 + 20.0 * np.sin(0.1 * 2*np.pi * t)  # deg/s
        yaw = (yaw_rate * t) * deg2rad
        
        # Add sudden "flip" maneuvers every 15 seconds
        if int(t) % 15 == 0 and (t % 1.0) < 0.5:  # 0.5s flip window
            pitch = pitch + 30.0 * deg2rad * np.sin(10 * t)
    
    # ========================================================================
    # LEVEL 4: CHAOTIC/UNPREDICTABLE DISTURBANCE REJECTION (EXTREME)
    # ========================================================================
    elif level in ['extreme', '4', 'level4', 4]:
        # Combination of random walk, multi-frequency, and sudden disturbances
        # Simulates extreme turbulence or adversarial conditions
        
        # Pseudo-random component (deterministic but looks random)
        np.random.seed(int(t * 100) % 10000)  # Changes every 0.01s
        random_pitch = np.random.uniform(-5, 5) * deg2rad
        random_roll = np.random.uniform(-5, 5) * deg2rad
        random_yaw = np.random.uniform(-10, 10) * deg2rad
        
        # Multi-frequency sinusoidal base
        pitch_base = (12.0 * np.sin(0.4 * 2*np.pi * t) + 
                      6.0 * np.sin(0.7 * 2*np.pi * t) +
                      3.0 * np.sin(1.2 * 2*np.pi * t)) * deg2rad
        
        roll_base = (15.0 * np.sin(0.35 * 2*np.pi * t) + 
                     7.0 * np.sin(0.9 * 2*np.pi * t) +
                     4.0 * np.cos(1.5 * 2*np.pi * t)) * deg2rad
        
        yaw_base = (25.0 * np.sin(0.2 * 2*np.pi * t) +
                    15.0 * np.sin(0.5 * 2*np.pi * t)) * deg2rad
        
        # Sudden step disturbances every 10 seconds
        disturbance_pitch = 0.0
        disturbance_roll = 0.0
        if int(t) % 10 == 0 and (t % 1.0) < 1.0:
            disturbance_pitch = 20.0 * deg2rad * (1 - (t % 1.0))
            disturbance_roll = -15.0 * deg2rad * (1 - (t % 1.0))
        
        # Combine all components
        pitch = pitch_base + random_pitch + disturbance_pitch
        roll = roll_base + random_roll + disturbance_roll
        yaw = yaw_base + random_yaw
        
        # Saturation (physical limits)
        pitch = np.clip(pitch, -35 * deg2rad, 35 * deg2rad)
        roll = np.clip(roll, -35 * deg2rad, 35 * deg2rad)
        yaw = np.clip(yaw, -180 * deg2rad, 180 * deg2rad)
    
    else:
        raise ValueError(f"Invalid level '{level}'. Use 'easy', 'medium', 'hard', or 'extreme'")
    
    # Return as column vector
    return np.array([[wrap_angle(pitch)], [wrap_angle(roll)], [wrap_angle(yaw)]])

