# 📊 BARRIER FUNCTION VISUAL COMPARISON
# ============================================
# Compare logarithmic vs prescribed performance barriers

import matplotlib.pyplot as plt
import numpy as np

# ============================================
# BARRIER FUNCTION DEFINITIONS
# ============================================

def logarithmic_barrier_vis(x, x_max, alpha=0.75, smoothing=0.01):
    """Current implementation: Logarithmic barrier"""
    activation_threshold = alpha * x_max
    if x <= activation_threshold:
        return 0.0
    else:
        remaining_margin = x_max - x + smoothing
        if remaining_margin <= smoothing:
            remaining_margin = smoothing
        return -np.log(remaining_margin)

def logarithmic_barrier_derivative_vis(x, x_max, alpha=0.75, smoothing=0.01):
    """Derivative of logarithmic barrier"""
    activation_threshold = alpha * x_max
    if x <= activation_threshold:
        return 0.0
    else:
        remaining_margin = x_max - x + smoothing
        if remaining_margin <= smoothing:
            remaining_margin = smoothing
        return 1.0 / remaining_margin

def prescribed_performance_barrier_vis(e_norm, eps):
    """Previous implementation: Prescribed performance barrier derivative
    
    Note: e_norm = sqrt(e.T @ P @ e) is the weighted error norm
    """
    if e_norm >= eps - 1e-10:  # Avoid division by zero
        return 1e6  # Very large number (approaching infinity)
    
    # Original formula: phid = (eps - 0.5*sqrt(e.T @ P @ e)) / (eps - sqrt(e.T @ P @ e))^2
    numerator = eps - 0.5 * e_norm
    denominator = (eps - e_norm)**2
    
    if abs(denominator) < 1e-12:
        return 1e6
    
    return numerator / denominator

