# VISUALIZATION PARAMETERS
# ============================================

# Logarithmic barrier params (current)
x_max_angle = np.deg2rad(15.0)  # Max angle error [rad]
x_max_rate = 1.5  # Max rate error [rad/s]
alpha = 0.75
smoothing = 0.01

# Prescribed performance params (previous)
eps_angle = 0.005  # Prescribed bound (from previous code)

# ============================================
# PLOT 1: ANGLE ERROR BARRIERS
