fig, axes = plt.subplots(2, 2, figsize=(16, 12))

# Create error range (from 0 to limit)
x_angle = np.linspace(0, x_max_angle, 500)
x_rate = np.linspace(0, x_max_rate, 500)

# Compute logarithmic barriers for angle
phi_log_angle = np.array([logarithmic_barrier_vis(x, x_max_angle, alpha, smoothing) for x in x_angle])
dphi_log_angle = np.array([logarithmic_barrier_derivative_vis(x, x_max_angle, alpha, smoothing) for x in x_angle])

# Compute prescribed performance barrier for angle (using e_norm directly as scalar)
# Note: For fair comparison, we treat the angle error as the "norm" 
phi_pp_angle = np.array([prescribed_performance_barrier_vis(x, eps_angle) for x in x_angle])

# SUBPLOT 1: Logarithmic Barrier (Angle)
axes[0, 0].plot(np.rad2deg(x_angle), phi_log_angle, linewidth=2.5, color='#1f77b4', label='φ(x)')
axes[0, 0].axvline(x=alpha*np.rad2deg(x_max_angle), color='orange', linestyle='--', 
                    linewidth=2, label=f'Activation (α={alpha})')
