# SUBPLOT 2: Logarithmic Barrier Derivative (Angle)
axes[0, 1].plot(np.rad2deg(x_angle), dphi_log_angle, linewidth=2.5, color='#ff7f0e', label='dφ/dx')
axes[0, 1].axvline(x=alpha*np.rad2deg(x_max_angle), color='orange', linestyle='--', 
                    linewidth=2, label=f'Activation (α={alpha})')
axes[0, 1].axvline(x=np.rad2deg(x_max_angle), color='red', linestyle='--', 
                    linewidth=2, label=f'Hard Limit')
axes[0, 1].set_xlabel('Angle Error [degrees]', fontsize=12)
axes[0, 1].set_ylabel('Barrier Derivative dφ/dx', fontsize=12)
axes[0, 1].set_title('Logarithmic Barrier Derivative (CURRENT)', fontsize=14, fontweight='bold')
axes[0, 1].legend(loc='upper left', fontsize=11)
axes[0, 1].grid(True, alpha=0.3)
axes[0, 1].set_ylim([-0.5, 50])

# SUBPLOT 3: Prescribed Performance Barrier (Angle)
axes[1, 0].plot(np.rad2deg(x_angle), phi_pp_angle, linewidth=2.5, color='#2ca02c', label='φ_d(||e||_P)')
axes[1, 0].axvline(x=np.rad2deg(eps_angle), color='red', linestyle='--', 
                    linewidth=2, label=f'Prescribed Bound ε={eps_angle:.4f} rad')
