# 🎛️ BARRIER FUNCTION SELECTOR
# ============================================
# Choose which barrier implementation to use in your simulation

class BarrierFunctionType:
    """Enumeration for barrier function types"""
    LOGARITHMIC = "logarithmic"           # Current: Component-wise, inactive region
    PRESCRIBED_PERFORMANCE = "prescribed"  # Previous: Lyapunov-based, always active

# ============================================
# USER CONFIGURATION - CHANGE THIS!
# ============================================

SELECTED_BARRIER = BarrierFunctionType.LOGARITHMIC  # ← CHANGE THIS TO SWITCH

# ============================================
# IMPLEMENTATION: LOGARITHMIC BARRIER
# ============================================

def logarithmic_barrier_final(x, x_max, alpha=0.75, smoothing=0.01):
    """
    Logarithmic barrier function (CURRENT IMPLEMENTATION)
    - Inactive when x < alpha * x_max
    - Grows to infinity as x → x_max
    """
    activation_threshold = alpha * x_max
    
    if x <= activation_threshold:
        return 0.0
    else:
        remaining_margin = x_max - x + smoothing
        if remaining_margin <= smoothing:
            remaining_margin = smoothing
        return -np.log(remaining_margin)

def logarithmic_barrier_derivative_final(x, x_max, alpha=0.75, smoothing=0.01):
    """Derivative of logarithmic barrier"""
    activation_threshold = alpha * x_max
    
    if x <= activation_threshold:
        return 0.0
    else:
        remaining_margin = x_max - x + smoothing
        if remaining_margin <= smoothing:
            remaining_margin = smoothing
        return 1.0 / remaining_margin

def composite_error_barrier_log(e_vec, e_max_angle, e_max_rate, alpha, smoothing):
    """
    Composite logarithmic barrier for [angle_error, rate_error] vector
    """
    angle_error = np.abs(e_vec[0, 0])
    rate_error = np.abs(e_vec[1, 0])
    
    phi_angle = logarithmic_barrier_final(angle_error, e_max_angle, alpha, smoothing)
    phi_rate = logarithmic_barrier_final(rate_error, e_max_rate, alpha, smoothing)
    
    return phi_angle + phi_rate

def barrier_gradient_modifier_log(What, grad, e_vec, theta, e_max_angle, e_max_rate, 
                                   alpha, gain, smoothing, P, B):
    """
    Gradient modification using logarithmic barrier
    """
    angle_error = e_vec[0, 0]
    rate_error = e_vec[1, 0]
    
    dphi_dangle = logarithmic_barrier_derivative_final(np.abs(angle_error), e_max_angle, alpha, smoothing)
    dphi_drate = logarithmic_barrier_derivative_final(np.abs(rate_error), e_max_rate, alpha, smoothing)
    
    # Apply sign
    if angle_error != 0:
        dphi_dangle *= np.sign(angle_error)
    if rate_error != 0:
        dphi_drate *= np.sign(rate_error)
    
    dphi_de = np.array([[dphi_dangle], [dphi_drate]])
    grad_barrier = gain * theta @ (dphi_de.T @ P @ B)
    
    return grad_barrier

# ============================================
# IMPLEMENTATION: PRESCRIBED PERFORMANCE BARRIER
# ============================================

def prescribed_performance_barrier_final(e_vec, P, eps):
    """
    Prescribed performance barrier (PREVIOUS IMPLEMENTATION)
    
    Args:
        e_vec: Error vector [2x1]
        P: Lyapunov matrix [2x2]
        eps: Prescribed error bound (scalar)
    
    Returns:
        phid: Barrier function derivative
        v: Control modification term
    """
    # Compute weighted error norm
    e_norm = np.sqrt((e_vec.T @ P @ e_vec).item())
    
    # Avoid division by zero
    if e_norm >= eps - 1e-10:
        phid = 1e6  # Very large (approaching infinity)
    else:
        numerator = eps - 0.5 * e_norm
        denominator = (eps - e_norm)**2
        phid = numerator / max(denominator, 1e-12)
    
    return phid, e_norm

def composite_error_barrier_pp(e_vec, P, B, eps, qhat):
    """
    Composite prescribed performance barrier with control modification
    
    Returns:
        phi_val: Barrier value for logging
        v: Control modification term
    """
    phid, e_norm = prescribed_performance_barrier_final(e_vec, P, eps)
    
    # Control modification: v = tanh(phid * B.T @ P @ e) * qhat
    v = np.tanh(phid * (B.T @ P @ e_vec).item()) * qhat
    
    return e_norm, v  # Return norm for logging, v for control

def barrier_gradient_modifier_pp(What, grad, e_vec, theta, P, B, eps, qhat):
    """
    Gradient modification using prescribed performance barrier
    
    Note: This implementation is adapted to work with the projection operator
    in the current code. The original used different update laws.
    """
    phid, e_norm = prescribed_performance_barrier_final(e_vec, P, eps)
    
    # Projection regressor from previous code
    # PR = phid * theta @ (e_vec.T @ P @ B)
    grad_barrier = phid * theta @ (e_vec.T @ P @ B)
    
    return grad_barrier

# ============================================
# UNIFIED INTERFACE - USE THIS IN SIMULATION
# ============================================

def apply_barrier_function(e_vec, e_max_angle, e_max_rate, theta, P, B, 
                           barrier_config, qhat=1.0):
    """
    Unified interface for applying barrier functions
    
    Returns:
        phi_val: Barrier value (for logging)
        grad_modifier: Gradient modification term
        v_term: Control modification (for prescribed performance only)
    """
    if SELECTED_BARRIER == BarrierFunctionType.LOGARITHMIC:
        # Logarithmic barrier
        phi_val = composite_error_barrier_log(
            e_vec, e_max_angle, e_max_rate,
            barrier_config.BARRIER_ALPHA, 
            barrier_config.BARRIER_SMOOTHING
        )
        
        grad_modifier = barrier_gradient_modifier_log(
            None, None, e_vec, theta, e_max_angle, e_max_rate,
            barrier_config.BARRIER_ALPHA,
            1.0,  # gain (typically handled in adaptation law)
            barrier_config.BARRIER_SMOOTHING,
            P, B
        )
        
        v_term = 0.0  # No additional control term
        
    elif SELECTED_BARRIER == BarrierFunctionType.PRESCRIBED_PERFORMANCE:
        # Prescribed performance barrier
        eps = (e_max_angle + e_max_rate) / 2.0  # Average as combined bound
        
        e_norm, v_term = composite_error_barrier_pp(e_vec, P, B, eps, qhat)
        phi_val = e_norm  # Use norm as "barrier value"
        
        grad_modifier = barrier_gradient_modifier_pp(
            None, None, e_vec, theta, P, B, eps, qhat
        )
    else:
        raise ValueError(f"Unknown barrier type: {SELECTED_BARRIER}")
    
    return phi_val, grad_modifier, v_term

