print("Starting Simulation...")

# Debug counter for periodic status updates
debug_counter = 0
debug_interval = 500  # Print every 500 steps

for t in np.arange(0, ft, dt):
    
    # 1. Get Command & Environment
    r = compute_reference_trajectory(t, level='hard')
    
    # BARRIER-AWARE REFERENCE GOVERNOR (if enabled)
    if BarrierConfig.ENABLE_CONTROL_BARRIER:
        # Ensure reference doesn't require excessive control
        u_max_vec = np.array([U_MAX_PITCH_ROLL, U_MAX_PITCH_ROLL, U_MAX_YAW])
        #r_feasible = constrain_reference(
        #    r, x, u_prev, u_max_vec, 
        #    BarrierConfig.U_FEASIBLE_MARGIN,
        #    K1, K2, dt, BarrierConfig.TAU_REF_GOVERNOR
        #)
        #r_filtered += dt * 4.0 * (r_feasible - r_filtered)
    else:
        # Pre-filter reference slightly to smooth steps
        r_filtered += dt * 4.0 * (r - r_filtered)
    
    if Config.TIME_VARYING_UNCERTAINTY:
        if Config.USE_STRUCTURED_UNCERTAINTY:
            W_true_pitch, W_true_roll, W_true_yaw = compute_time_varying_uncertainty(
                t, x, level='hard', use_structured=True
            )
        else:
            W_true_pitch, W_true_roll, W_true_yaw = compute_time_varying_uncertainty(
                t, x, level='hard', use_structured=False, 
                num_rbf_per_state=NUM_RBF_PER_STATE, use_joint_rbf=Config.USE_JOINT_RBF
            )

    # 2. Extract Axis States & Compute Regressors
    pitch, dp = x[0,0], x[1,0]
    roll, dr = x[2,0], x[3,0]
    yaw, dy = x[4,0], x[5,0]
    
    # Compute basis functions
    if Config.USE_STRUCTURED_UNCERTAINTY:
        theta_base_pitch = compute_basis(1.0, pitch, dp, dr*dy, True, 'pitch')
        theta_base_roll = compute_basis(1.0, roll, dr, dp*dy, True, 'roll')
        theta_base_yaw = compute_basis(1.0, yaw, dy, dp*dr, True, 'yaw')
    else:
        theta_base_pitch = compute_basis(1.0, pitch, dp, dr*dy, False, 'pitch', RBF_RANGE['pitch'], Config.USE_JOINT_RBF)
        theta_base_roll = compute_basis(1.0, roll, dr, dp*dy, False, 'roll', RBF_RANGE['roll'], Config.USE_JOINT_RBF)
        theta_base_yaw = compute_basis(1.0, yaw, dy, dp*dr, False, 'yaw', RBF_RANGE['yaw'], Config.USE_JOINT_RBF)
    
    # Extend regressor if using Lambda compensation
    if Config.INCLUDE_CONTROL_IN_REGRESSOR:
        theta_pitch = compute_extended_regressor(theta_base_pitch, un_prev[0], v_prev[0,0])
        theta_roll = compute_extended_regressor(theta_base_roll, un_prev[1], v_prev[1,0])
        theta_yaw  = compute_extended_regressor(theta_base_yaw, un_prev[2], v_prev[2,0])
    else:
        theta_pitch, theta_roll, theta_yaw = theta_base_pitch, theta_base_roll, theta_base_yaw

    # 3. Compute Adaptive Control (ua)
    if Config.ADAPTATION_ON:
        ua_pitch = -What_pitch.T @ theta_pitch
        ua_roll = -What_roll.T @ theta_roll
        ua_yaw = -What_yaw.T @ theta_yaw
        
        # Saturation
        if Config.USE_ADAPTIVE_SATURATION:
            ua_pitch = np.clip(ua_pitch, -MAX_ADAPTIVE_TORQUE['pitch'], MAX_ADAPTIVE_TORQUE['pitch'])
            ua_roll  = np.clip(ua_roll,  -MAX_ADAPTIVE_TORQUE['roll'],  MAX_ADAPTIVE_TORQUE['roll'])
            ua_yaw   = np.clip(ua_yaw,   -MAX_ADAPTIVE_TORQUE['yaw'],   MAX_ADAPTIVE_TORQUE['yaw'])
            
        ua = np.array([ua_pitch.item(), ua_roll.item(), ua_yaw.item()])
    else:
        ua = np.zeros(3)

    # 4. Performance Recovery (v)
    if Config.PERFORMANCE_RECOVERY_ON:
        e_state = x - xm
        
        # Simplified L1 predictor dynamics
        lam_diag = np.diag([PerfRec.LAMBDA['pitch']]*2 + [PerfRec.LAMBDA['roll']]*2 + [PerfRec.LAMBDA['yaw']]*2)
        f += dt * (-lam_diag @ (f - e_state))
        
        g = lam_diag @ f + (Am - lam_diag) @ e_state
        v_raw = np.linalg.pinv(B_full) @ g
        
        if PerfRec.USE_FILTERED:
            taus = np.array([[PerfRec.TAU_V['pitch']], [PerfRec.TAU_V['roll']], [PerfRec.TAU_V['yaw']]])
            v_filtered += dt * (v_raw - v_filtered) / taus
            v = v_filtered
        else:
            v = v_raw
    else:
        v = np.zeros((3,1))

    # 5. Nominal Control (un)
    un_feedback = (-K1 @ x).flatten()
    un_feedforward = (K2 @ r_filtered).flatten()
    un = un_feedback + un_feedforward + v.flatten()


    u = un + ua  # Total control command before saturation

    # CRITICAL: Apply control saturation IMMEDIATELY to prevent integrator-like windup
    # This ensures u stays within physical limits before any further processing
    u = np.array([
        np.clip(u[0], -U_MAX_PITCH_ROLL, U_MAX_PITCH_ROLL),
        np.clip(u[1], -U_MAX_PITCH_ROLL, U_MAX_PITCH_ROLL),
        np.clip(u[2], -U_MAX_YAW, U_MAX_YAW)
    ])

    # 6. ACTUATOR DYNAMICS (The Real World)
    # ---------------------------------------------------------
    if Config.ENABLE_ACTUATOR_DYNAMICS:
        # A. Use the already-saturated control command
        u_saturated = u.copy()
        
        # B. Scale Torque to Normalized Motor Mix
        # CRITICAL FIX: At hover (throttle = 0.23), the ACTUAL achievable
        # torque range is limited by the smaller headroom (0.23, not 1.0).
        # We normalize using the ACHIEVABLE range, not theoretical max.
        #
        # Achievable torque at hover = HOVER_THROTTLE * U_MAX
        U_ACHIEVABLE_PITCH_ROLL = HOVER_THROTTLE * U_MAX_PITCH_ROLL  # ~0.5 Nm
        U_ACHIEVABLE_YAW = HOVER_THROTTLE * U_MAX_YAW                # ~0.35 Nm
        
        # Normalize: convert from [-U_ACHIEVABLE, +U_ACHIEVABLE] to [-HOVER, +HOVER]
        # This ensures motor commands stay in [0, 2*HOVER] range before clipping
        norm_pitch = u_saturated[0] / U_MAX_PITCH_ROLL * HOVER_THROTTLE
        norm_roll  = u_saturated[1] / U_MAX_PITCH_ROLL * HOVER_THROTTLE
        norm_yaw   = u_saturated[2] / U_MAX_YAW * HOVER_THROTTLE
        
        # NO pre-mixer scaling needed now - the normalization is correct!
        # Motor commands will be in range [HOVER - norm, HOVER + norm]
        # With norm in [-HOVER, +HOVER], this gives [0, 2*HOVER] max range

        # C. Mixer (Quad X Configuration)
        # Calculate target motor speeds (0.0 to 1.0)
        # Motor Layout: M1(RR), M2(FR), M3(RL), M4(FL)
        motor_cmds = np.zeros(4)
        motor_cmds[0] = HOVER_THROTTLE - norm_pitch + norm_roll - norm_yaw  # M1 (Rear-Right)
        motor_cmds[1] = HOVER_THROTTLE + norm_pitch + norm_roll + norm_yaw  # M2 (Front-Right)
        motor_cmds[2] = HOVER_THROTTLE - norm_pitch - norm_roll + norm_yaw  # M3 (Rear-Left)
        motor_cmds[3] = HOVER_THROTTLE + norm_pitch - norm_roll - norm_yaw  # M4 (Front-Left)

        # E. Safety clip (should rarely trigger now due to pre-mixer scaling)
        motor_cmds = np.clip(motor_cmds, 0.0, 1.0)

        # D. Motor Lag (First-Order Dynamics)
        # Real motors can't change speed instantly - they have inertia
        # Exponential approach: speed += (target - speed) * dt / tau
        current_motor_speeds += (motor_cmds - current_motor_speeds) * (dt / MOTOR_TAU)

        # E. Inverse Mixer: Convert ACTUAL motor speeds back to physical torques
        # The torques that are ACTUALLY applied to the body based on what the motors are doing
        # This is the KEY difference from ideal control!
        
        # CORRECTED INVERSE MIXER:
        # Each motor contributes to torques based on its position and direction
        # For X-frame quad: Pitch = (Front - Back), Roll = (Right - Left)
        # The mixer weights are typically ±1, so we need to invert with the same weights
        
        # Pitch Torque: Front motors (M2,M4) spin up → positive pitch
        #               Back motors (M1,M3) spin up → negative pitch
        p_motor = (current_motor_speeds[1] + current_motor_speeds[3]) - \
                  (current_motor_speeds[0] + current_motor_speeds[2])
        
        # CORRECTED Roll Torque:
        # In forward mixer: +roll → M1,M2 increase, M3,M4 decrease
        # So inverse: r_motor = (M1+M2) - (M3+M4) gives positive when roll is positive
        r_motor = (current_motor_speeds[0] + current_motor_speeds[1]) - \
                  (current_motor_speeds[2] + current_motor_speeds[3])
        
        # CORRECTED Yaw Torque:
        # In forward mixer: +yaw → M2,M3 increase (CCW motors), M1,M4 decrease (CW motors)
        # So inverse: y_motor = (M2+M3) - (M1+M4) gives positive when yaw is positive
        y_motor = (current_motor_speeds[1] + current_motor_speeds[2]) - \
                  (current_motor_speeds[0] + current_motor_speeds[3])
        
        # CORRECTED SCALING: Convert motor differential back to physical torque (Nm)
        # NEW MATH with updated normalization:
        #   Forward: norm_pitch = u / U_MAX * HOVER_THROTTLE
        #   Mixer adds ±norm_pitch to 4 motors
        #   Inverse: p_motor = (M2+M4) - (M1+M3) = 4 * norm_pitch = 4 * (u / U_MAX * HOVER)
        #   Therefore: u = p_motor * U_MAX / (4 * HOVER)
        u_applied = np.array([
            (p_motor / (4.0 * HOVER_THROTTLE)) * U_MAX_PITCH_ROLL,  # Pitch torque [Nm]
            (r_motor / (4.0 * HOVER_THROTTLE)) * U_MAX_PITCH_ROLL,  # Roll torque [Nm]
            (y_motor / (4.0 * HOVER_THROTTLE)) * U_MAX_YAW          # Yaw torque [Nm]
        ])
    else:
        # IDEAL MODE: Direct torque application (no motor dynamics)
        # Still saturate to physical limits for realism
        u_saturated = np.array([
            np.clip(u[0], -U_MAX_PITCH_ROLL, U_MAX_PITCH_ROLL),
            np.clip(u[1], -U_MAX_PITCH_ROLL, U_MAX_PITCH_ROLL),
            np.clip(u[2], -U_MAX_YAW, U_MAX_YAW)
        ])
        u_applied = u_saturated.copy()
    
    # ---------------------------------------------------------
    
    # Store u_prev for next iteration
    u_prev = u_applied.copy()
    
    # Store for next step (Algebraic loop prevention)
    un_prev = un.copy()
    v_prev = v.copy()

    # 7. Update System State (Integration)
    #    Real Physics: x_dot = A*x + B*Lambda*(u + Uncertainty)
    
    # Calculate true uncertainty torque (using base basis only)
    unc_pitch = (W_true_pitch.T @ theta_base_pitch).item()
    unc_roll = (W_true_roll.T @ theta_base_roll).item()
    unc_yaw = (W_true_yaw.T @ theta_base_yaw).item()
    
    # PHYSICAL REALISM: Cap uncertainty to be within realistic disturbance levels
    # CRITICAL: Uncertainty must be less than ACTUAL control authority!
    # At hover throttle 0.23, actual control authority is only HOVER * U_MAX per axis
    U_ACTUAL_PITCH_ROLL = HOVER_THROTTLE * U_MAX_PITCH_ROLL  # ~0.5 Nm actual authority
    U_ACTUAL_YAW = HOVER_THROTTLE * U_MAX_YAW                # ~0.35 Nm actual authority
    
    # Allow uncertainty up to 60% of actual control authority (leaving 40% for compensation)
    UNC_MAX_PITCH_ROLL = 0.6 * U_ACTUAL_PITCH_ROLL  # ~0.3 Nm max disturbance
    UNC_MAX_YAW = 0.6 * U_ACTUAL_YAW                 # ~0.21 Nm max disturbance
    
    unc_pitch = np.clip(unc_pitch, -UNC_MAX_PITCH_ROLL, UNC_MAX_PITCH_ROLL)
    unc_roll = np.clip(unc_roll, -UNC_MAX_PITCH_ROLL, UNC_MAX_PITCH_ROLL)
    unc_yaw = np.clip(unc_yaw, -UNC_MAX_YAW, UNC_MAX_YAW)
    
    unc_vec = np.array([[unc_pitch], [unc_roll], [unc_yaw]])

    # Real Plant Dynamics
    x += dt * (A_full @ x + B_full @ Lambda_true @ (u_applied.reshape(-1,1) + unc_vec))
    
    # PHYSICAL REALISM: Clamp angular rates to physically reasonable bounds
    # A real drone would crash long before reaching these rates, but we clamp to prevent
    # numerical overflow while still allowing the system to show instability
    MAX_ANGULAR_RATE = 50.0  # rad/s (~2865 deg/s - very aggressive maneuver limit)
    x[1,0] = np.clip(x[1,0], -MAX_ANGULAR_RATE, MAX_ANGULAR_RATE)  # pitch rate
    x[3,0] = np.clip(x[3,0], -MAX_ANGULAR_RATE, MAX_ANGULAR_RATE)  # roll rate
    x[5,0] = np.clip(x[5,0], -MAX_ANGULAR_RATE, MAX_ANGULAR_RATE)  # yaw rate
    
    # Reference Model with BOTH Performance Recovery AND Pseudo-Control Hedging
    # Hedge: Prevents ref model from diverging when actuators saturate/lag
    # v: Compensates for matched/unmatched uncertainties
    # IMPORTANT: Use u_saturated (clamped command) not raw u for realistic hedge
    u_deficit = u_applied - u_saturated  # Difference between achieved vs attempted (after saturation)
    hedge_signal = B_full @ (u_deficit.reshape(-1,1))
    
    xm += dt * (Am @ xm + Bm @ r_filtered + hedge_signal + (B_full @ v if Config.PERFORMANCE_RECOVERY_ON else 0))
    xr += dt * (Am @ xr + Bm @ r_filtered) # Pure reference model (for comparison)

    # 8. Adaptive Law Update
    if Config.ADAPTATION_ON:
        e_pitch_vec = x[[0,1], :] - xm[[0,1], :]
        e_roll_vec = x[[2,3], :] - xm[[2,3], :]
        e_yaw_vec = x[[4,5], :] - xm[[4,5], :]

        # Deadzone Logic
        err_degs = [np.abs(e[0]*180/np.pi).item() for e in [e_pitch_vec, e_roll_vec, e_yaw_vec]]
        deadzones = []
        
        for i, axis in enumerate(['pitch', 'roll', 'yaw']):
            if Config.USE_ADAPTIVE_DEADZONE and err_degs[i] < DEADZONE_THRESHOLD:
                settled_time[axis] += dt
                deadzones.append(0.0)
            else:
                settled_time[axis] = 0.0
                deadzones.append(1.0)
        
        # Gamma scheduling
        gammas = {}
        for axis in ['pitch', 'roll', 'yaw']:
            g = get_scheduled_gamma(t, GAMMA_FINAL[axis], TAU_GAMMA) if Config.USE_GAMMA_SCHEDULING else GAMMA_FINAL[axis]
            gammas[axis] = g

        # Projection Operator
        def Projection_operator(What, grad, What_Proj_tol, limits):
            PR = grad.copy()
            for i in range(What.shape[0]):
                for j in range(What.shape[1]):
                    if What[i,j] > limits[1] - What_Proj_tol and grad[i,j] > 0:
                        PR[i,j] = (limits[1] - What[i,j])/What_Proj_tol * grad[i,j]
                    elif What[i,j] < limits[0] + What_Proj_tol and grad[i,j] < 0:
                        PR[i,j] = (limits[0] - What[i,j])/What_Proj_tol * grad[i,j]
            return PR

        def update_weight(What, Whatf, theta, e_vec, gamma, sigma, Proj_range_limits, Proj_tol, SIGMA_LF_F, deadzone):
            norm = (1 + theta.T @ theta).item() if Config.USE_WEIGHT_NORMALIZATION else 1.0
            sigma = sigma if Config.SIGMA_MODIFICATION else 0.0
            grad = theta @ (e_vec.T @ P_single_axis @ B_single_axis) * deadzone
            
            if Config.USE_LOW_FREQUENCY_LEARNING:
                grad_normalized = grad / norm
                if Config.PROJECTION_OPERATOR:
                    grad_projected = Projection_operator(What, grad_normalized, Proj_tol, Proj_range_limits)
                else:
                    grad_projected = grad_normalized
                update_direction = grad_projected - SIGMA_LF_F * (What - Whatf) / norm - sigma * What / norm
                What += dt * gamma * update_direction
                Whatf += dt * GAM_F * (What - Whatf)
            else:
                grad_normalized = grad / norm
                if Config.PROJECTION_OPERATOR:
                    grad_projected = Projection_operator(What, grad_normalized, Proj_tol, Proj_range_limits)
                else:
                    grad_projected = grad_normalized
                update_term = grad_projected - sigma * What / norm
                What += dt * gamma * update_term
                Whatf += dt * GAM_F * (What - Whatf)
            return What, Whatf
        
        What_pitch, Whatf_pitch = update_weight(What_pitch, Whatf_pitch, theta_pitch, e_pitch_vec, gammas['pitch'], SIGMA['pitch'], What_Proj_limits['pitch'], What_Proj_tol['pitch'], SIGMA_LF_F['pitch'], deadzones[0])
        What_roll, Whatf_roll = update_weight(What_roll, Whatf_roll, theta_roll, e_roll_vec, gammas['roll'], SIGMA['roll'], What_Proj_limits['roll'], What_Proj_tol['roll'], SIGMA_LF_F['roll'], deadzones[1])
        What_yaw, Whatf_yaw = update_weight(What_yaw, Whatf_yaw, theta_yaw, e_yaw_vec, gammas['yaw'], SIGMA['yaw'], What_Proj_limits['yaw'], What_Proj_tol['yaw'], SIGMA_LF_F['yaw'], deadzones[2])

    # 9. Logging
    log['t'].append(t)
    log['x'].append(x.flatten().copy())
    log['xm'].append(xm.flatten().copy())
    log['xr'].append(xr.flatten().copy())
    log['u'].append(u.flatten().copy())
    log['ua'].append(ua.flatten().copy())
    log['un'].append(un.flatten().copy())
    log['unc_true'].append(unc_vec.flatten().copy())
    log['e'].append((x - xm).flatten().copy())
    log['u_applied'].append(u_applied.flatten().copy())
    log['What_pitch'].append(What_pitch.flatten().copy())
    log['What_roll'].append(What_roll.flatten().copy())
    log['What_yaw'].append(What_yaw.flatten().copy())
    log['theta_pitch'].append(theta_pitch.flatten().copy())
    log['theta_roll'].append(theta_roll.flatten().copy())
    log['theta_yaw'].append(theta_yaw.flatten().copy())
    log['v'].append(v.flatten().copy())
    
    # Periodic diagnostic output
    debug_counter += 1
    if debug_counter % debug_interval == 0:
        # Check for numerical issues
        if np.any(np.isnan(x)) or np.any(np.isinf(x)):
            print(f"\n⚠️  WARNING at t={t:.3f}s: NaN/Inf detected in state!")
            print(f"  x = {x.flatten()}")
            print(f"  u = {u}")
            print(f"  u_applied = {u_applied}")
            break
        if np.any(np.abs(x) > 1000):
            print(f"\n⚠️  WARNING at t={t:.3f}s: State overflow detected!")
            print(f"  x = {x.flatten()}")
            print(f"  u = {u}")
            print(f"  u_applied = {u_applied}")
            break

print("Simulation Completed! Processing data...")

# Convert logs to numpy arrays for plotting
for key in log:
    log[key] = np.array(log[key])

print(f"Data points recorded: {len(log['t'])}")
