# BarrierConfig.E_MAX_ROLL = 15.0
# BarrierConfig.BARRIER_GAIN = {'pitch': 2.5, 'roll': 2.5, 'yaw': 2.0}
# BarrierConfig.BARRIER_ALPHA = 0.75
# BarrierConfig.ENABLE_ERROR_BARRIER = True
# ```
