# BARRIER FUNCTION TUNING GUIDANCE
# ============================================
# Analyzes barrier gradient impact and provides tuning recommendations

print("="*90)
print("🎛️  BARRIER FUNCTION TUNING ANALYSIS")
print("="*90)

if BarrierConfig.ENABLE_ERROR_BARRIER and len(log['barrier_grad_norm_pitch']) > 0:
    
    # Extract gradient norms
    grad_bar_norm_pitch = np.array(log['barrier_grad_norm_pitch'])
    grad_bar_norm_roll = np.array(log['barrier_grad_norm_roll'])
    grad_bar_norm_yaw = np.array(log['barrier_grad_norm_yaw'])
    
    # Extract tracking errors for correlation analysis
    e_rec = np.array(log['e'])
    e_pitch_angle = np.abs(e_rec[:, 0]) * 180/np.pi
    e_roll_angle = np.abs(e_rec[:, 2]) * 180/np.pi
    e_yaw_angle = np.abs(e_rec[:, 4]) * 180/np.pi
    
    print("\n📈 BARRIER GRADIENT STATISTICS:")
    print("="*90)
    
    tuning_recommendations = {}
    
    for axis, grad_norm, e_angle, e_max, current_gain in [
        ('Pitch', grad_bar_norm_pitch, e_pitch_angle, BarrierConfig.E_MAX_PITCH, BarrierConfig.BARRIER_GAIN['pitch']),
        ('Roll', grad_bar_norm_roll, e_roll_angle, BarrierConfig.E_MAX_ROLL, BarrierConfig.BARRIER_GAIN['roll']),
        ('Yaw', grad_bar_norm_yaw, e_yaw_angle, BarrierConfig.E_MAX_YAW, BarrierConfig.BARRIER_GAIN['yaw'])
    ]:
        # Statistics when barrier is active
        active_mask = grad_norm > 1e-6
        
        if np.any(active_mask):
            max_grad = np.max(grad_norm[active_mask])
            mean_grad = np.mean(grad_norm[active_mask])
            peak_error_when_active = np.max(e_angle[active_mask])
            
            # Compute correlation between error magnitude and gradient strength
            if np.sum(active_mask) > 10:
                correlation = np.corrcoef(e_angle[active_mask], grad_norm[active_mask])[0, 1]
            else:
                correlation = 0.0
            
            print(f"\n{axis} Axis:")
            print(f"  Current barrier gain:        {current_gain:.2f}")
            print(f"  Max barrier gradient norm:   {max_grad:.4f}")
            print(f"  Mean gradient (when active): {mean_grad:.4f}")
            print(f"  Peak error when active:      {peak_error_when_active:.2f}° (limit: {e_max:.2f}°)")
            print(f"  Error-gradient correlation:  {correlation:.3f}")
            
            # Tuning recommendations based on performance
            margin_to_limit = e_max - peak_error_when_active
            margin_pct = (margin_to_limit / e_max) * 100
            
            recommendations = []
            
            if margin_pct < 5:
                # Very close to limit - need stronger barrier
                recommended_gain = current_gain * 1.5
                recommendations.append(
                    f"⚠️  CRITICAL: Only {margin_pct:.1f}% margin! "
                    f"Increase gain to ~{recommended_gain:.1f} for better enforcement"
                )
            elif margin_pct < 15:
                # Adequate but could be tighter
                recommended_gain = current_gain * 1.2
                recommendations.append(
                    f"ℹ️  Moderate margin ({margin_pct:.1f}%). "
                    f"Consider increasing gain to ~{recommended_gain:.1f} for more conservative behavior"
                )
            elif margin_pct > 50:
                # Very conservative - could reduce gain for better performance
                recommended_gain = current_gain * 0.7
                recommendations.append(
                    f"ℹ️  Large margin ({margin_pct:.1f}%). "
                    f"Could reduce gain to ~{recommended_gain:.1f} for better tracking performance"
                )
            else:
                recommendations.append(
                    f"✅ Well-tuned! Margin of {margin_pct:.1f}% provides good balance"
                )
            
            if correlation < 0.7:
                recommendations.append(
                    "⚠️  Weak error-gradient correlation. Consider decreasing BARRIER_ALPHA "
                    f"(current: {BarrierConfig.BARRIER_ALPHA:.2f}) for earlier activation"
                )
            
            print(f"\n  Recommendations:")
            for rec in recommendations:
                print(f"    • {rec}")
            
            tuning_recommendations[axis.lower()] = {
                'current_gain': current_gain,
                'recommended_gain': recommended_gain if margin_pct < 15 or margin_pct > 50 else current_gain,
                'margin_pct': margin_pct,
                'recommendations': recommendations
            }
        else:
            print(f"\n{axis} Axis:")
            print(f"  Barrier never activated - error always below threshold")
            print(f"  Current gain ({current_gain:.2f}) may be too conservative")
            tuning_recommendations[axis.lower()] = {
                'current_gain': current_gain,
                'recommended_gain': current_gain,
                'margin_pct': 100.0,
                'recommendations': ["ℹ️  Barrier not needed for this trajectory"]
            }
    
    # Plot barrier gradient magnitudes vs tracking error
    fig, axes = plt.subplots(3, 1, figsize=(12, 9))
    fig.suptitle('Barrier Gradient Magnitude vs. Tracking Error', fontsize=14, fontweight='bold')
    
    gradient_data = [
        ('Pitch', grad_bar_norm_pitch, e_pitch_angle, BarrierConfig.E_MAX_PITCH),
        ('Roll', grad_bar_norm_roll, e_roll_angle, BarrierConfig.E_MAX_ROLL),
        ('Yaw', grad_bar_norm_yaw, e_yaw_angle, BarrierConfig.E_MAX_YAW)
    ]
    
    t_vec = np.array(log['t'])
    
    for ax, (axis_name, grad_norm, e_angle, e_max) in zip(axes, gradient_data):
        # Twin axis plot
        ax_grad = ax
        ax_err = ax.twinx()
        
        # Plot gradient on left axis
        line1 = ax_grad.plot(t_vec, grad_norm, 'g-', linewidth=1.5, alpha=0.7, label='Barrier Gradient Norm')
        ax_grad.set_ylabel('Gradient Norm', fontsize=10, color='g')
        ax_grad.tick_params(axis='y', labelcolor='g')
        ax_grad.set_yscale('log')
        ax_grad.set_ylim([1e-6, np.max(grad_norm) * 2])
        
        # Plot error on right axis
        line2 = ax_err.plot(t_vec, e_angle, 'b-', linewidth=1.5, alpha=0.7, label='Tracking Error')
        ax_err.axhline(e_max, color='red', linestyle='--', linewidth=2, alpha=0.7, label='Constraint Limit')
        ax_err.set_ylabel(f'{axis_name} Error [deg]', fontsize=10, color='b')
        ax_err.tick_params(axis='y', labelcolor='b')
        ax_err.set_ylim([0, e_max * 1.3])
        
        # Combined legend
        lines = line1 + line2 + [plt.Line2D([0], [0], color='red', linestyle='--', linewidth=2)]
        labels = ['Barrier Gradient', 'Tracking Error', 'Constraint Limit']
        ax_grad.legend(lines, labels, loc='upper left', fontsize=8)
        
        ax_grad.set_title(f'{axis_name} Axis', fontsize=11, fontweight='bold')
        ax_grad.grid(True, alpha=0.3, which='both')
    
    axes[-1].set_xlabel('Time [s]', fontsize=10)
    plt.tight_layout()
    plt.show()
    
    # Summary recommendations
    print("\n" + "="*90)
    print("📋 SUMMARY OF TUNING RECOMMENDATIONS:")
    print("="*90)
    
    print("\nProposed new barrier gains:")
    print("```python")
    print("BarrierConfig.BARRIER_GAIN = {")
    for axis in ['pitch', 'roll', 'yaw']:
        if axis in tuning_recommendations:
            rec_gain = tuning_recommendations[axis]['recommended_gain']
            print(f"    '{axis}': {rec_gain:.1f},")
    print("}")
    print("```")
    
    print("\nGeneral tuning guidelines:")
    print("  1. BARRIER_GAIN: Higher = stronger constraint enforcement, but may increase control effort")
    print("  2. BARRIER_ALPHA: Lower = earlier activation (0.7-0.9 typical)")
    print("  3. E_MAX_*: Set based on safety requirements - barrier will enforce these limits")
    print("  4. Watch for oscillations: If barrier causes chatter, reduce BARRIER_GAIN or increase BARRIER_ALPHA")
    
    # Interaction with other MRAC mechanisms
    print("\n" + "="*90)
    print("🔗 INTERACTION WITH EXISTING MRAC MECHANISMS:")
    print("="*90)
    print("\n Barrier functions work alongside:")
    print("  ✅ Projection Operator: Barrier bounds ERROR, projection bounds PARAMETERS")
    print("  ✅ Sigma Modification: Barrier enforces constraints, sigma prevents drift")
    print("  ✅ L1 Adaptive Law: Barrier gradient adds to L1 filtered gradient")
    print("  ✅ Performance Recovery: Both work to maintain tracking within bounds")
    print("\n  These mechanisms are complementary - enabling all provides robust safety!")
    
else:
    print("\n⚠️  Barrier functions not enabled or no gradient data available.")
    print("   Enable barriers and run simulation to see tuning analysis.")

