# Detects high-frequency oscillations in angle and rate tracking

from scipy import signal
from scipy.fft import fft, fftfreq

print("=" * 90)
print("🔍 DIAGNOSTIC 1: OSCILLATION ANALYSIS")
print("=" * 90)

def analyze_oscillations(data, t, name, dt):
    """Analyze oscillation characteristics of a signal."""
    results = {}
    
    # Remove DC component (mean)
    data_centered = data - np.mean(data)
    
    # Compute FFT
    n = len(data)
    freqs = fftfreq(n, dt)[:n//2]
    fft_vals = np.abs(fft(data_centered))[:n//2]
    
    # Find dominant frequencies (excluding DC)
    min_freq_idx = int(0.5 / (freqs[1] - freqs[0])) if len(freqs) > 1 else 1  # Exclude below 0.5 Hz
    if min_freq_idx < len(fft_vals):
        dominant_idx = np.argmax(fft_vals[min_freq_idx:]) + min_freq_idx
        dominant_freq = freqs[dominant_idx]
        dominant_power = fft_vals[dominant_idx]
    else:
        dominant_freq = 0
        dominant_power = 0
    
    # Compute high-frequency energy ratio (>5 Hz vs total)
    hf_threshold = 5.0  # Hz
    hf_idx = np.where(freqs > hf_threshold)[0]
    lf_idx = np.where((freqs > 0.1) & (freqs <= hf_threshold))[0]
    
    total_power = np.sum(fft_vals[1:]**2)  # Exclude DC
    hf_power = np.sum(fft_vals[hf_idx]**2) if len(hf_idx) > 0 else 0
    lf_power = np.sum(fft_vals[lf_idx]**2) if len(lf_idx) > 0 else 0
    
    hf_ratio = hf_power / total_power if total_power > 0 else 0
    
    # Zero-crossing rate (indicates oscillation frequency)
    zero_crossings = np.sum(np.diff(np.sign(data_centered)) != 0)
    zc_rate = zero_crossings / (t[-1] - t[0])  # crossings per second
    
    # Peak-to-peak in different time windows
    window_size = int(1.0 / dt)  # 1 second window
    local_pp = []
    for i in range(0, len(data) - window_size, window_size // 2):
        window = data[i:i+window_size]
        local_pp.append(np.max(window) - np.min(window))
    
    results['dominant_freq'] = dominant_freq
    results['dominant_power'] = dominant_power
    results['hf_ratio'] = hf_ratio
    results['zc_rate'] = zc_rate
    results['mean_local_pp'] = np.mean(local_pp) if local_pp else 0
    results['max_local_pp'] = np.max(local_pp) if local_pp else 0
    results['freqs'] = freqs
    results['fft_vals'] = fft_vals
    
    return results

# Analyze each axis
oscillation_issues = {'pitch': [], 'roll': [], 'yaw': []}
