    # Peak demand vs available
    peak_demand = np.max(np.abs(u_total))
    peak_uncertainty = np.max(np.abs(unc_true))
    
    # Control headroom
    headroom = u_actual_hover - peak_demand
    headroom_percent = headroom / u_actual_hover * 100 if u_actual_hover > 0 else 0
    
    # Adaptive vs nominal ratio
    adaptive_ratio = np.mean(np.abs(u_adaptive)) / (np.mean(np.abs(u_nominal)) + 1e-10)
    
    # Rate of change analysis
    u_rate = np.diff(u_total) / dt
    max_rate = np.max(np.abs(u_rate))
