print(f"  Damping Ratio (ζ):       {zeta:.3f}")

# Theoretical performance
theoretical_settling = 4 / (zeta * wn)
theoretical_rise = 1.8 / wn
theoretical_overshoot = np.exp(-zeta * np.pi / np.sqrt(1 - zeta**2)) * 100 if zeta < 1 else 0
theoretical_bandwidth = wn * np.sqrt(1 - 2*zeta**2 + np.sqrt(4*zeta**4 - 4*zeta**2 + 2))

print(f"\nTheoretical Performance (2nd order model):")
print(f"  Expected settling time (2%):  {theoretical_settling:.2f} s")
print(f"  Expected rise time:           {theoretical_rise:.2f} s")
print(f"  Expected overshoot:           {theoretical_overshoot:.1f}%")
print(f"  Bandwidth (-3dB):             {theoretical_bandwidth:.2f} rad/s ({theoretical_bandwidth/(2*np.pi):.2f} Hz)")

# Actual performance measurement
print(f"\n{'─'*40}")
print("📊 Actual vs Expected Performance")
print(f"{'─'*40}")

reference_model_issues = []

for i, axis_name in enumerate(['Pitch', 'Roll', 'Yaw']):
    angle_err = [e_pitch_rec[:, 0], e_roll_rec[:, 0], e_yaw_rec[:, 0]][i]
    ref_signal = xr_rec[:, i*2]  # Reference angle
    actual_signal = x_rec[:, i*2]  # Actual angle
    
    # Find step responses (look for significant reference changes)
    ref_diff = np.abs(np.diff(ref_signal))
    step_indices = np.where(ref_diff > 1.0)[0]  # Steps > 1 degree
    
    if len(step_indices) > 0:
        # Analyze first significant step
        step_idx = step_indices[0]
        step_start = max(0, step_idx - 10)
        step_end = min(len(t_rec) - 1, step_idx + int(5 / dt))  # 5 seconds after step
        
        # Measure actual settling time
        step_magnitude = np.abs(ref_signal[step_end] - ref_signal[step_start])
        if step_magnitude > 0.1:
            threshold_2pct = 0.02 * step_magnitude
            post_step_error = np.abs(actual_signal[step_idx:step_end] - ref_signal[step_idx:step_end])
            
            settled_mask = post_step_error < threshold_2pct
            if np.any(settled_mask):
                # Find first time it settles and stays settled
                for j in range(len(settled_mask)):
                    if np.all(settled_mask[j:min(j+50, len(settled_mask))]):
                        actual_settling = (j) * dt
                        break
                else:
                    actual_settling = float('inf')
            else:
                actual_settling = float('inf')
            
            # Measure overshoot
            steady_state = ref_signal[step_end]
            if step_magnitude > 0:
                overshoot_vals = (actual_signal[step_idx:step_end] - steady_state) / step_magnitude
                actual_overshoot = np.max(overshoot_vals) * 100 if np.max(overshoot_vals) > 0 else 0
            else:
                actual_overshoot = 0
            
            print(f"\n  {axis_name}:")
            print(f"    Actual settling time:   {actual_settling:.2f} s (expected: {theoretical_settling:.2f} s)")
            print(f"    Actual overshoot:       {actual_overshoot:.1f}% (expected: {theoretical_overshoot:.1f}%)")
            
            # Assess issues
            if actual_settling > 2 * theoretical_settling:
                reference_model_issues.append(f"{axis_name}: Settling {actual_settling/theoretical_settling:.1f}x slower than expected")
            if actual_overshoot > theoretical_overshoot + 10:
                reference_model_issues.append(f"{axis_name}: Overshoot {actual_overshoot - theoretical_overshoot:.0f}% higher than expected")

# Bandwidth assessment
print(f"\n{'─'*40}")
print("📊 Bandwidth Assessment")
print(f"{'─'*40}")

# Estimate effective motor bandwidth
motor_bandwidth_est = 1 / (5 * MOTOR_TAU)  # Rule of thumb: BW ≈ 1/(5τ)
motor_bandwidth_hz = motor_bandwidth_est

print(f"\n  Reference model bandwidth:    {theoretical_bandwidth/(2*np.pi):.2f} Hz")
print(f"  Estimated motor bandwidth:    {motor_bandwidth_hz:.2f} Hz")
print(f"  Ratio (ref/motor):            {(theoretical_bandwidth/(2*np.pi))/motor_bandwidth_hz:.2f}")

# Safe bandwidth rule: ref_BW < 0.2 * motor_BW
safe_ref_bw = 0.2 * motor_bandwidth_hz
safe_wn = safe_ref_bw * 2 * np.pi / np.sqrt(1 - 2*zeta**2 + np.sqrt(4*zeta**4 - 4*zeta**2 + 2))

if theoretical_bandwidth/(2*np.pi) > 0.3 * motor_bandwidth_hz:
    reference_model_issues.append(
        f"Reference BW ({theoretical_bandwidth/(2*np.pi):.1f} Hz) may exceed safe limit "
        f"(~{0.3*motor_bandwidth_hz:.1f} Hz = 0.3 × motor BW)"
    )
    print(f"\n  ⚠️  Reference model may be TOO FAST for motor dynamics!")
    print(f"      Safe ωₙ estimate: {safe_wn:.1f} rad/s (current: {wn:.1f} rad/s)")

# Summary and recommendations
print(f"\n{'='*90}")
print("📋 REFERENCE MODEL ASSESSMENT SUMMARY")
print("="*90)

if reference_model_issues:
    print("\n⚠️  Issues Detected:")
    for issue in reference_model_issues:
        print(f"   • {issue}")
    
    print("\n🛠️  RECOMMENDATIONS:")
    if any("slower" in issue for issue in reference_model_issues):
        print(f"   • Consider INCREASING ωₙ from {wn:.1f} to {wn*1.3:.1f} rad/s for faster response")
    if any("higher" in issue.lower() and "overshoot" in issue.lower() for issue in reference_model_issues):
        print(f"   • Consider INCREASING ζ from {zeta:.2f} to {min(0.95, zeta+0.1):.2f} to reduce overshoot")
    if any("exceed" in issue.lower() or "fast" in issue.lower() for issue in reference_model_issues):
        print(f"   • Consider REDUCING ωₙ from {wn:.1f} to {safe_wn:.1f} rad/s")
        print(f"   • Or upgrade motors with faster response (lower τ)")
else:
    print("\n✅ Reference model parameters appear well-suited for the system!")

