# ─────────────────────────────────────────────────────────────────────────────
# Step 1: Gather System Constraints
# ─────────────────────────────────────────────────────────────────────────────

print("\n📐 SYSTEM CONSTRAINTS ANALYSIS")
print("─" * 60)

# Motor bandwidth constraint
motor_bandwidth_hz = 1 / (5 * MOTOR_TAU)
motor_bandwidth_rad = motor_bandwidth_hz * 2 * np.pi
print(f"  Motor time constant (τ):       {MOTOR_TAU:.3f} s")
print(f"  Estimated motor bandwidth:     {motor_bandwidth_hz:.2f} Hz ({motor_bandwidth_rad:.1f} rad/s)")

# Control authority constraint
# Maximum angular acceleration = max_torque / inertia
J_avg = (Jx + Jy) / 2  # Average for pitch/roll
max_torque_pr = U_ACTUAL_PITCH_ROLL if 'U_ACTUAL_PITCH_ROLL' in dir() else HOVER_THROTTLE * U_MAX_PITCH_ROLL
max_angular_accel = max_torque_pr / J_avg
print(f"  Max control torque (P/R):      {max_torque_pr:.3f} N·m")
print(f"  Average inertia (P/R):         {J_avg:.6f} kg·m²")
print(f"  Max angular acceleration:      {max_angular_accel:.1f} rad/s²")

# Typical step command magnitude
typical_step_deg = 20  # degrees
typical_step_rad = typical_step_deg * np.pi / 180
wn_accel_limit = np.sqrt(max_angular_accel / typical_step_rad)
print(f"  For {typical_step_deg}° step, max ωₙ:   {wn_accel_limit:.1f} rad/s")

# Sensor noise consideration (assuming MPU6050-like)
gyro_noise_dps = 0.05  # degrees per second typical
gyro_noise_rad = gyro_noise_dps * np.pi / 180
# Rule: keep ωₙ such that noise amplification at ωₙ is acceptable
# Noise amplification ≈ ωₙ / ζ for rate feedback
wn_noise_limit = 20.0  # Empirical limit for typical IMUs

print(f"  Assumed gyro noise:            {gyro_noise_dps:.3f} °/s")
print(f"  ωₙ limit from noise:           ~{wn_noise_limit:.1f} rad/s")

# ─────────────────────────────────────────────────────────────────────────────
# Step 2: Compute Recommended ωₙ Range
# ─────────────────────────────────────────────────────────────────────────────

print("\n📊 RECOMMENDED ωₙ RANGE")
print("─" * 60)

# Conservative rule: ωₙ < 0.2 × motor_bandwidth
wn_conservative = 0.15 * motor_bandwidth_rad
wn_moderate = 0.25 * motor_bandwidth_rad
wn_aggressive = 0.35 * motor_bandwidth_rad

# Also constrained by acceleration
wn_conservative = min(wn_conservative, 0.7 * wn_accel_limit)
wn_moderate = min(wn_moderate, 0.85 * wn_accel_limit)
wn_aggressive = min(wn_aggressive, wn_accel_limit)

# Also constrained by noise
wn_conservative = min(wn_conservative, 0.6 * wn_noise_limit)
wn_moderate = min(wn_moderate, 0.8 * wn_noise_limit)
wn_aggressive = min(wn_aggressive, wn_noise_limit)

print(f"  Conservative ωₙ:               {wn_conservative:.1f} rad/s ({wn_conservative/(2*np.pi):.2f} Hz)")
print(f"  Moderate ωₙ:                   {wn_moderate:.1f} rad/s ({wn_moderate/(2*np.pi):.2f} Hz)")
print(f"  Aggressive ωₙ:                 {wn_aggressive:.1f} rad/s ({wn_aggressive/(2*np.pi):.2f} Hz)")
print(f"\n  Current ωₙ:                    {wn:.1f} rad/s ({wn/(2*np.pi):.2f} Hz)")

# Assess current ωₙ
if wn > wn_aggressive:
    wn_assessment = "TOO HIGH - likely causing oscillations"
    wn_color = "❌"
elif wn > wn_moderate:
    wn_assessment = "AGGRESSIVE - may cause oscillations under disturbance"
    wn_color = "⚠️"
elif wn > wn_conservative:
    wn_assessment = "MODERATE - good balance"
    wn_color = "✅"
else:
    wn_assessment = "CONSERVATIVE - very stable but may be sluggish"
    wn_color = "🐢"

print(f"\n  Assessment: {wn_color} {wn_assessment}")

# ─────────────────────────────────────────────────────────────────────────────
# Step 3: Compute Recommended ζ
# ─────────────────────────────────────────────────────────────────────────────

print("\n📊 RECOMMENDED ζ (DAMPING RATIO)")
print("─" * 60)

# Check if oscillations were detected
has_oscillations = any('OSCILLATION' in issue for issue in 
                       all_issues.get('critical', []) + all_issues.get('warning', []))

if has_oscillations:
    zeta_recommended = min(0.95, zeta + 0.15)
    print(f"  ⚠️  Oscillations detected!")
    print(f"  Current ζ = {zeta:.2f} may be too low")
    print(f"  Recommended: ζ = {zeta_recommended:.2f} (increased for stability)")
else:
    if zeta < 0.6:
        zeta_recommended = 0.7
        print(f"  Current ζ = {zeta:.2f} is quite low (oscillatory response expected)")
    elif zeta > 0.95:
        zeta_recommended = 0.85
        print(f"  Current ζ = {zeta:.2f} is quite high (sluggish response)")
    else:
        zeta_recommended = zeta
        print(f"  Current ζ = {zeta:.2f} is in good range")

print(f"\n  Recommended ζ range: 0.70 - 0.90")
print(f"  Optimal for most cases: ζ = 0.707 (Butterworth)")

# ─────────────────────────────────────────────────────────────────────────────
# Step 4: Generate Specific Recommendations
# ─────────────────────────────────────────────────────────────────────────────

print("\n" + "=" * 90)
print("🎯 SPECIFIC RECOMMENDATIONS FOR YOUR SYSTEM")
print("=" * 90)

# Determine recommended values
if has_oscillations or wn > wn_aggressive:
    wn_recommended = wn_conservative
    zeta_recommended = max(0.8, zeta_recommended)
    scenario = "OSCILLATION_REDUCTION"
else:
    wn_recommended = wn_moderate
    scenario = "BALANCED"

# Calculate expected performance
ts_recommended = 4 / (zeta_recommended * wn_recommended)
overshoot_recommended = np.exp(-zeta_recommended * np.pi / np.sqrt(1 - zeta_recommended**2)) * 100 if zeta_recommended < 1 else 0

print(f"\n┌{'─'*86}┐")
print(f"│ {'SCENARIO: ' + scenario:<84} │")
print(f"├{'─'*86}┤")
print(f"│ {'CURRENT':<20} │ {'RECOMMENDED':<20} │ {'EXPECTED IMPROVEMENT':<40} │")
print(f"├{'─'*86}┤")
print(f"│ ωₙ = {wn:<14.1f} │ ωₙ = {wn_recommended:<14.1f} │ {'Reduces HF oscillation' if wn > wn_recommended else 'Maintains stability':<40} │")
print(f"│ ζ  = {zeta:<14.2f} │ ζ  = {zeta_recommended:<14.2f} │ {'Increases damping' if zeta_recommended > zeta else 'Maintains response':<40} │")
print(f"├{'─'*86}┤")
print(f"│ Expected settling time: {ts_recommended:<6.2f} s                                                 │")
print(f"│ Expected overshoot:     {overshoot_recommended:<6.1f} %                                                 │")
print(f"└{'─'*86}┘")

# Copyable code
print("\n📋 COPY-PASTE CODE:")
print("─" * 60)
print("```python")
print(f"# Recommended reference model parameters")
print(f"wn = {wn_recommended:.1f}    # Natural frequency [rad/s]")
print(f"zeta = {zeta_recommended:.2f}  # Damping ratio")
print(f"")
print(f"# Expected performance:")
print(f"# - Settling time (2%): {ts_recommended:.2f} s")
print(f"# - Overshoot: {overshoot_recommended:.1f}%")
print("```")

# ─────────────────────────────────────────────────────────────────────────────
# Step 5: Generate ωₙ-ζ Design Space Plot
# ─────────────────────────────────────────────────────────────────────────────

fig_wn_zeta, (ax_wn, ax_zeta) = plt.subplots(1, 2, figsize=(14, 5))

# Plot 1: ωₙ design space
wn_range = np.linspace(0.5, 15, 100)
ax_wn.axvspan(0, wn_conservative, alpha=0.2, color='green', label='Conservative')
ax_wn.axvspan(wn_conservative, wn_moderate, alpha=0.2, color='yellow', label='Moderate')
ax_wn.axvspan(wn_moderate, wn_aggressive, alpha=0.2, color='orange', label='Aggressive')
ax_wn.axvspan(wn_aggressive, 15, alpha=0.2, color='red', label='Risky')

ax_wn.axvline(wn, color='blue', linewidth=2, linestyle='-', label=f'Current: {wn:.1f}')
ax_wn.axvline(wn_recommended, color='green', linewidth=2, linestyle='--', label=f'Recommended: {wn_recommended:.1f}')

# Add constraint lines
ax_wn.axvline(0.2 * motor_bandwidth_rad, color='purple', linestyle=':', alpha=0.7, label=f'0.2×Motor BW')
ax_wn.axvline(0.7 * wn_accel_limit, color='brown', linestyle=':', alpha=0.7, label=f'0.7×Accel limit')

ax_wn.set_xlabel('ωₙ (rad/s)', fontsize=12)
ax_wn.set_ylabel('Design Region', fontsize=12)
ax_wn.set_title('Natural Frequency Design Space', fontsize=12, fontweight='bold')
ax_wn.legend(loc='upper right', fontsize=8)
ax_wn.set_xlim([0, 15])
ax_wn.grid(True, alpha=0.3)

# Plot 2: ζ vs performance tradeoff
zeta_range = np.linspace(0.3, 1.0, 100)
overshoot_curve = np.array([np.exp(-z * np.pi / np.sqrt(1 - z**2)) * 100 if z < 1 else 0 for z in zeta_range])
settling_factor = 4 / (zeta_range * wn_recommended)  # Normalized to wn=1

ax_zeta2 = ax_zeta.twinx()
ax_zeta.plot(zeta_range, overshoot_curve, 'b-', linewidth=2, label='Overshoot (%)')
ax_zeta2.plot(zeta_range, settling_factor, 'r-', linewidth=2, label='Settling time factor')

ax_zeta.axvline(zeta, color='blue', linestyle='--', alpha=0.7, label=f'Current ζ={zeta:.2f}')
ax_zeta.axvline(zeta_recommended, color='green', linestyle='--', alpha=0.7, label=f'Recommended ζ={zeta_recommended:.2f}')
ax_zeta.axvline(0.707, color='gray', linestyle=':', alpha=0.5, label='Butterworth (0.707)')

ax_zeta.set_xlabel('Damping Ratio (ζ)', fontsize=12)
ax_zeta.set_ylabel('Overshoot (%)', color='blue', fontsize=12)
ax_zeta2.set_ylabel('Settling Time Factor (4/ζωₙ)', color='red', fontsize=12)
ax_zeta.set_title('Damping Ratio Tradeoff', fontsize=12, fontweight='bold')
ax_zeta.legend(loc='upper right', fontsize=8)
ax_zeta.grid(True, alpha=0.3)
ax_zeta.set_xlim([0.3, 1.0])

plt.suptitle('REFERENCE MODEL DESIGN SPACE', fontsize=14, fontweight='bold')
plt.tight_layout()
plt.show()

print("\n" + "=" * 90)
print("📖 INTERPRETATION GUIDE:")
print("=" * 90)
print("""
ωₙ Selection:
  • GREEN zone: Safe for most conditions, may feel sluggish
  • YELLOW zone: Good balance of speed and stability
  • ORANGE zone: Fast response, requires well-tuned adaptation
  • RED zone: High risk of oscillation, only for ideal conditions

ζ Selection:
  • ζ < 0.6: Significant overshoot, oscillatory feel
  • ζ = 0.707: Classic "optimal" - good balance (Butterworth response)
  • ζ = 0.8-0.9: Minimal overshoot, smooth response
  • ζ > 0.95: Very smooth but potentially sluggish
""")
print("=" * 90)

