# FIGURE: MOTOR SATURATION ANALYSIS (THE MIXER)
# =============================================================================
def simulated_mixer(u_log, hover_throttle=0.23):
    """
    Simulates Quad-X mixing to check for motor saturation.
    u_log: Array of shape (N, 3) containing [Pitch, Roll, Yaw] torques in Nm
    """
    n_steps = u_log.shape[0]
    motor_cmds = np.zeros((n_steps, 4)) # 4 Motors
    
    # Normalize torques (-1.0 to 1.0) based on physical limits
    norm_pitch = u_log[:, 0] / U_MAX_PITCH_ROLL
    norm_roll  = u_log[:, 1] / U_MAX_PITCH_ROLL
    norm_yaw   = u_log[:, 2] / U_MAX_YAW
    
    # Quad X Mixing Logic (Standard Betaflight/Cleanflight order)
    # 4   2   (CW   CCW)
    #   X
    # 3   1   (CCW  CW)
    
    # Note: Signs depend on your specific motor direction/index. 
    # Standard:
    # M1 (BR): -Pitch, +Roll, -Yaw
    # M2 (FR): +Pitch, +Roll, +Yaw
    # M3 (BL): -Pitch, -Roll, +Yaw
    # M4 (FL): +Pitch, -Roll, -Yaw
    
    motor_cmds[:, 0] = hover_throttle - norm_pitch + norm_roll - norm_yaw # M1
    motor_cmds[:, 1] = hover_throttle + norm_pitch + norm_roll + norm_yaw # M2
    motor_cmds[:, 2] = hover_throttle - norm_pitch - norm_roll + norm_yaw # M3
    motor_cmds[:, 3] = hover_throttle + norm_pitch - norm_roll - norm_yaw # M4
    
    return motor_cmds

# Run Mixer
motor_outputs = simulated_mixer(log['u'])

# Plot
