print(f"  λ (Roll):  {PerfRec.LAMBDA['roll']:.1f} rad/s")
print(f"  λ (Yaw):   {PerfRec.LAMBDA['yaw']:.1f} rad/s")

# ============================================================================
# STEP 3: Visualize L1-norm vs Lambda (The "Root Locus" Analogy)
# ============================================================================

fig_L1, axes_L1 = plt.subplots(2, 2, figsize=(14, 10))

# Plot 1: L1-norm vs Lambda
ax1 = axes_L1[0, 0]
ax1.loglog(lambda_sweep, L1_norms_pitch, 'b-', linewidth=2, label='||G(s,λ)||_L1')
ax1.axvline(lambda_star_pitch, color='r', linestyle='--', linewidth=2, label=f'λ* = {lambda_star_pitch:.1f}')
ax1.axvline(PerfRec.LAMBDA['pitch'], color='g', linestyle=':', linewidth=2, label=f'Current = {PerfRec.LAMBDA["pitch"]:.1f}')
