ax1.set_ylabel('L1-Norm ||G(s,λ)||', fontsize=12)
ax1.set_title('L1-Norm vs Filter Bandwidth (Pitch/Roll)', fontsize=13, fontweight='bold')
ax1.grid(True, which='both', alpha=0.3)
ax1.legend(fontsize=10)

# Plot 2: Stability Margin vs Lambda
ax2 = axes_L1[0, 1]
ax2.semilogx(lambda_sweep, margin_pitch, 'b-', linewidth=2, label='Pitch/Roll')
ax2.semilogx(lambda_sweep, margin_yaw, 'orange', linewidth=2, label='Yaw')
ax2.axhline(1.0, color='r', linestyle='--', linewidth=2, label='Stability Boundary')
ax2.axvline(lambda_star_pitch, color='r', linestyle='--', linewidth=1.5, alpha=0.5)
ax2.axvline(PerfRec.LAMBDA['pitch'], color='g', linestyle=':', linewidth=2)
ax2.fill_between(lambda_sweep, 0, 1, alpha=0.2, color='green', label='Stable Region')
ax2.fill_between(lambda_sweep, 1, 2, alpha=0.2, color='red', label='Unstable Region')
ax2.set_xlabel('Filter Bandwidth λ [rad/s]', fontsize=12)
ax2.set_ylabel('Stability Margin (||G||·L_max)', fontsize=12)
ax2.set_title('L1 Stability Condition: ||G(s,λ)||·L_max < 1', fontsize=13, fontweight='bold')
ax2.set_ylim([0, 2])
ax2.grid(True, which='both', alpha=0.3)
ax2.legend(fontsize=9)

# Plot 3: Effective Closed-Loop Poles (Root Locus Style)
ax3 = axes_L1[1, 0]
# For each lambda, compute effective closed-loop poles
# Simplified: show how dominant pole moves with lambda
lambda_samples = [1, 5, 10, 20, 50, 100, 200, lambda_star_pitch]
colors_rl = plt.cm.viridis(np.linspace(0, 1, len(lambda_samples)))

# Reference model poles (target)
ref_poles = np.roots([1, 2*zeta_current*wn_current, wn_current**2])
ax3.plot(ref_poles.real, ref_poles.imag, 'r*', markersize=15, label='Ref Model Poles', zorder=10)

for i, lam_val in enumerate(lambda_samples):
    # Effective closed-loop: H_eff(s) = C(s) * H_m(s) = (λ/(s+λ)) * H_m(s)
    # Poles of H_eff are: ref model poles + filter pole at -λ
    H_eff_num = [lam_val * wn_current**2]
    H_eff_den = np.convolve([1, 2*zeta_current*wn_current, wn_current**2], [1, lam_val])
    eff_poles = np.roots(H_eff_den)
    
    label_str = f'λ={lam_val:.0f}' if lam_val != lambda_star_pitch else f'λ*={lam_val:.1f}'
    ax3.plot(eff_poles.real, eff_poles.imag, 'o', color=colors_rl[i], 
             markersize=8, label=label_str, alpha=0.7)

ax3.axvline(0, color='k', linestyle='--', linewidth=1, alpha=0.3)
ax3.axhline(0, color='k', linestyle='--', linewidth=1, alpha=0.3)
ax3.set_xlabel('Real Part [rad/s]', fontsize=12)
ax3.set_ylabel('Imaginary Part [rad/s]', fontsize=12)
ax3.set_title('Effective Closed-Loop Pole Migration (Root Locus Style)', fontsize=13, fontweight='bold')
ax3.grid(True, alpha=0.3)
ax3.legend(fontsize=8, ncol=2)
ax3.set_xlim([-max(lambda_samples)*1.2, 5])

# Plot 4: Tracking Performance Metric
ax4 = axes_L1[1, 1]
# Performance metric: bandwidth of C(s)*H_m(s) as proxy for tracking speed
