ax4.semilogx(lambda_sweep, bandwidths, 'b-', linewidth=2)
ax4.axvline(lambda_star_pitch, color='r', linestyle='--', linewidth=2, label=f'λ* = {lambda_star_pitch:.1f}')
ax4.axvline(PerfRec.LAMBDA['pitch'], color='g', linestyle=':', linewidth=2, label=f'Current = {PerfRec.LAMBDA["pitch"]:.1f}')
