ax4.set_ylabel('Approx. Tracking Bandwidth [rad/s]', fontsize=12)
ax4.set_title('Tracking Performance vs λ', fontsize=13, fontweight='bold')
ax4.grid(True, which='both', alpha=0.3)
ax4.legend(fontsize=10)

plt.tight_layout()
plt.show()

